CREATE OR REPLACE FUNCTION private.generate_finance_insights(p_business_id uuid, p_period_start date, p_period_end date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_t0        timestamptz := clock_timestamp();
  v_actor     uuid := auth.uid();
  v_biz       uuid := p_business_id;
  v_access    boolean := false;
  v_ver       text := 'v1';
  v_th        jsonb := public.finance_insight_thresholds();
  v_today     date := public.ar_today();
  v_len       integer;
  v_cmp_start date;
  v_cmp_end   date;
  v_fired     jsonb := '[]'::jsonb;
  v_skipped   jsonb := '[]'::jsonb;
  v_keep      text[] := ARRAY[]::text[];

  v_ns_cur numeric; v_ns_prev numeric; v_gp_cur numeric; v_gp_prev numeric;
  v_cogs_cur numeric; v_cogs_prev numeric;
  v_cash_cur numeric; v_cash_prev numeric; v_ar_delta numeric;
  v_liquidity numeric;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;
  IF v_biz IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'business_id requerido');
  END IF;
  SELECT (EXISTS (SELECT 1 FROM public.businesses WHERE id = v_biz AND owner_user_id = v_actor)
       OR EXISTS (SELECT 1 FROM public.profiles WHERE business_id = v_biz
                    AND COALESCE(user_id, id) = v_actor AND COALESCE(is_active, true)))
    INTO v_access;
  IF NOT v_access THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin acceso a este negocio');
  END IF;

  IF p_period_start IS NULL OR p_period_end IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Periodo requerido');
  END IF;
  IF p_period_end < p_period_start THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Periodo invalido');
  END IF;
  v_len := (p_period_end - p_period_start) + 1;
  IF v_len > 366 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Periodo demasiado largo (max 366 dias)');
  END IF;
  IF p_period_start > v_today THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Periodo en el futuro');
  END IF;

  v_cmp_end   := p_period_start - 1;
  v_cmp_start := v_cmp_end - (v_len - 1);

  PERFORM pg_advisory_xact_lock(
    hashtext('finance_insights:' || v_biz::text || ':' || p_period_start::text
             || ':' || p_period_end::text || ':' || v_ver));

  SELECT COALESCE(SUM(net_sales),0), COALESCE(SUM(gross_profit),0), COALESCE(SUM(cogs),0)
    INTO v_ns_cur, v_gp_cur, v_cogs_cur
    FROM public.v_finance_pnl
   WHERE business_id = v_biz AND period_date BETWEEN p_period_start AND p_period_end;

  SELECT COALESCE(SUM(net_sales),0), COALESCE(SUM(gross_profit),0), COALESCE(SUM(cogs),0)
    INTO v_ns_prev, v_gp_prev, v_cogs_prev
    FROM public.v_finance_pnl
   WHERE business_id = v_biz AND period_date BETWEEN v_cmp_start AND v_cmp_end;

  SELECT COALESCE(SUM(net_ars),0) INTO v_cash_cur
    FROM public.v_finance_cashflow
   WHERE business_id = v_biz AND cashflow_class = 'operating' AND is_reversal = false
     AND movement_date_ar BETWEEN p_period_start AND p_period_end;

  SELECT COALESCE(SUM(net_ars),0) INTO v_cash_prev
    FROM public.v_finance_cashflow
   WHERE business_id = v_biz AND cashflow_class = 'operating' AND is_reversal = false
     AND movement_date_ar BETWEEN v_cmp_start AND v_cmp_end;

  SELECT COALESCE(SUM(c.saldo_pendiente),0) INTO v_ar_delta
    FROM public.comprobantes c
    JOIN public.v_finance_effective_comprobantes e
      ON e.id = c.id AND e.is_credit_note = false
   WHERE c.business_id = v_biz AND e.period_date BETWEEN p_period_start AND p_period_end
     AND c.saldo_pendiente > 0.01 AND c.customer_id IS NOT NULL;

  SELECT COALESCE(cash_total,0) INTO v_liquidity
    FROM public.v_finance_position WHERE business_id = v_biz;
  v_liquidity := COALESCE(v_liquidity, 0);

  -- R1. margin_drop_cost
  IF v_ns_cur <= 0 OR v_ns_prev <= 0 THEN
    v_skipped := v_skipped || jsonb_build_object('rule_id','margin_drop_cost','reason','no_sales_in_one_period');
  ELSE
    DECLARE
      m_cur numeric := ROUND(v_gp_cur / NULLIF(v_ns_cur,0) * 100, 2);
      m_prv numeric := ROUND(v_gp_prev / NULLIF(v_ns_prev,0) * 100, 2);
      c_cur numeric := ROUND(v_cogs_cur / NULLIF(v_ns_cur,0) * 100, 2);
      c_prv numeric := ROUND(v_cogs_prev / NULLIF(v_ns_prev,0) * 100, 2);
    BEGIN
      IF (m_cur - m_prv) <= -(v_th->'margin_drop_cost'->>'margin_drop_pp')::numeric
         AND (c_cur - c_prv) >= (v_th->'margin_drop_cost'->>'cogs_rise_pp')::numeric THEN
        v_fired := v_fired || jsonb_build_object(
          'rule_id','margin_drop_cost','severity','warning',
          'title','El margen bajó por aumento de costo',
          'message','El margen bruto cayó respecto del período anterior y el costo de mercadería subió como proporción de cada venta. No se explica por vender menos.',
          'impact_ars', ROUND(ABS(m_cur - m_prv) / 100 * v_ns_cur, 2),
          'evidence', jsonb_build_object(
            'metric','gross_margin_pct','current_value',m_cur,'comparison_value',m_prv,
            'delta', ROUND(m_cur - m_prv, 2), 'delta_percent', NULL,
            'cogs_ratio_current', c_cur, 'cogs_ratio_previous', c_prv,
            'net_sales_current', v_ns_cur, 'net_sales_previous', v_ns_prev,
            'threshold', v_th->'margin_drop_cost',
            'period_start', p_period_start, 'period_end', p_period_end,
            'comparison_period_start', v_cmp_start, 'comparison_period_end', v_cmp_end,
            'sample_size', v_len, 'currency','ARS','source','v_finance_pnl',
            'calculation_version', v_ver),
          'action', jsonb_build_object('label','Ver cálculo','target_type','drawer','target','calculation','params', jsonb_build_object()));
      END IF;
    END;
  END IF;

  -- R2. cash_down_sales_up
  IF v_ns_prev <= 0 OR v_cash_prev = 0 THEN
    v_skipped := v_skipped || jsonb_build_object('rule_id','cash_down_sales_up','reason','no_comparison_base');
  ELSE
    DECLARE
      s_delta numeric := ROUND((v_ns_cur - v_ns_prev) / NULLIF(ABS(v_ns_prev),0) * 100, 2);
      c_delta numeric := ROUND((v_cash_cur - v_cash_prev) / NULLIF(ABS(v_cash_prev),0) * 100, 2);
    BEGIN
      IF s_delta >= (v_th->'cash_down_sales_up'->>'sales_up_pct')::numeric
         AND c_delta <= (v_th->'cash_down_sales_up'->>'cash_down_pct')::numeric THEN
        v_fired := v_fired || jsonb_build_object(
          'rule_id','cash_down_sales_up','severity','warning',
          'title','La facturación devengada subió, pero los cobros bajaron',
          'message','La facturación devengada aumentó mientras los cobros operativos disminuyeron. Parte de las ventas del período quedó sin cobrar.',
          'impact_ars', ROUND(v_ar_delta, 2),
          'evidence', jsonb_build_object(
            'metric','accrued_vs_collected',
            'accrued_revenue', v_ns_cur, 'collected_cash', v_cash_cur,
            'accounts_receivable_delta', v_ar_delta,
            'current_value', v_cash_cur, 'comparison_value', v_cash_prev,
            'delta', ROUND(v_cash_cur - v_cash_prev, 2), 'delta_percent', c_delta,
            'sales_delta_percent', s_delta,
            'accrued_revenue_previous', v_ns_prev,
            'threshold', v_th->'cash_down_sales_up',
            'period_start', p_period_start, 'period_end', p_period_end,
            'comparison_period_start', v_cmp_start, 'comparison_period_end', v_cmp_end,
            'sample_size', v_len, 'currency','ARS',
            'source','v_finance_pnl + v_finance_cashflow',
            'calculation_version', v_ver),
          'action', jsonb_build_object('label','Ver cuentas corrientes','target_type','route','target','/cuentas','params', jsonb_build_object()));
      END IF;
    END;
  END IF;

  -- R3. dead_stock
  DECLARE
    v_dead_val numeric := 0; v_tot_val numeric := 0;
    v_dead_cnt bigint := 0;  v_tot_cnt bigint := 0;
    v_days int := (v_th->'dead_stock'->>'days')::int;
  BEGIN
    WITH universe AS (
      SELECT i.id, (i.stock_quantity * COALESCE(i.cost_price,0))::numeric AS val
        FROM public.inventory i
       WHERE i.business_id = v_biz AND i.is_active = true
         AND COALESCE(i.tipo,'product') = 'product'
         AND i.stock_quantity > 0 AND COALESCE(i.cost_price,0) > 0
         AND NOT EXISTS (SELECT 1 FROM public.inventory v
                          WHERE v.business_id = i.business_id
                            AND v.supplier_code = 'VPREF-' || i.id::text)
    ),
    last_sale AS (
      SELECT ci.inventory_id AS iid, MAX(e.period_date) AS d
        FROM public.comprobante_items ci
        JOIN public.v_finance_effective_comprobantes e
          ON e.id = ci.comprobante_id AND e.is_credit_note = false
       WHERE ci.business_id = v_biz AND ci.inventory_id IS NOT NULL
       GROUP BY 1
    ),
    last_mov AS (
      SELECT im.inventory_item_id AS iid,
             MAX((im.created_at AT TIME ZONE 'America/Argentina/Cordoba')::date) AS d
        FROM public.inventory_movements im
       WHERE im.business_id = v_biz
         AND im.movement_type IN ('sale','out','order_usage')
       GROUP BY 1
    )
    SELECT
      COALESCE(SUM(u.val) FILTER (WHERE GREATEST(COALESCE(ls.d,'-infinity'::date),
                                                 COALESCE(lm.d,'-infinity'::date))
                                       < v_today - v_days), 0),
      COALESCE(SUM(u.val), 0),
      COUNT(*) FILTER (WHERE GREATEST(COALESCE(ls.d,'-infinity'::date),
                                      COALESCE(lm.d,'-infinity'::date))
                            < v_today - v_days),
      COUNT(*)
      INTO v_dead_val, v_tot_val, v_dead_cnt, v_tot_cnt
      FROM universe u
      LEFT JOIN last_sale ls ON ls.iid = u.id
      LEFT JOIN last_mov  lm ON lm.iid = u.id;

    IF v_tot_cnt < (v_th->'dead_stock'->>'min_products')::int OR v_tot_val <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','dead_stock','reason','insufficient_inventory');
    ELSIF (v_dead_val / NULLIF(v_tot_val,0)) > (v_th->'dead_stock'->>'share')::numeric THEN
      v_fired := v_fired || jsonb_build_object(
        'rule_id','dead_stock','severity','warning',
        'title','Tenés capital inmovilizado',
        'message','Hay stock sin ventas ni consumo registrados en el plazo observado. Representa una porción significativa de tu inventario valorizado.',
        'impact_ars', ROUND(v_dead_val, 2),
        'evidence', jsonb_build_object(
          'metric','dead_stock_share',
          'current_value', ROUND(v_dead_val / NULLIF(v_tot_val,0), 4),
          'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
          'dead_value', ROUND(v_dead_val,2), 'inventory_at_cost', ROUND(v_tot_val,2),
          'dead_product_count', v_dead_cnt, 'total_product_count', v_tot_cnt,
          'days_threshold', v_days,
          'threshold', v_th->'dead_stock',
          'period_start', p_period_start, 'period_end', p_period_end,
          'comparison_period_start', NULL, 'comparison_period_end', NULL,
          'sample_size', v_tot_cnt, 'currency','ARS',
          'source','inventory + comprobante_items + inventory_movements',
          'calculation_version', v_ver),
        'action', jsonb_build_object('label','Ver inventario','target_type','route','target','/inventory','params', jsonb_build_object()));
    END IF;
  END;

  -- R4. withdrawals_vs_profit
  DECLARE
    v_win int := (v_th->'withdrawals_vs_profit'->>'window_days')::int;
    v_w_start date := p_period_end - (v_win - 1);
    v_res numeric; v_wd numeric;
  BEGIN
    SELECT COALESCE(SUM(operating_result),0) INTO v_res FROM public.v_finance_pnl
     WHERE business_id = v_biz AND period_date BETWEEN v_w_start AND p_period_end;
    SELECT COALESCE(SUM(amount),0) INTO v_wd FROM public.v_owner_flows
     WHERE business_id = v_biz AND flow_type = 'withdrawal' AND status = 'completed'
       AND date BETWEEN v_w_start AND p_period_end;

    IF v_res <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','withdrawals_vs_profit','reason','non_positive_result');
    ELSIF (v_wd / NULLIF(v_res,0)) > (v_th->'withdrawals_vs_profit'->>'share')::numeric THEN
      v_fired := v_fired || jsonb_build_object(
        'rule_id','withdrawals_vs_profit','severity','warning',
        'title','Los retiros superaron la ganancia',
        'message','Los retiros del dueño representan una proporción elevada del resultado operativo de la ventana observada.',
        'impact_ars', ROUND(v_wd, 2),
        'evidence', jsonb_build_object(
          'metric','withdrawals_over_result',
          'current_value', ROUND(v_wd / NULLIF(v_res,0), 4),
          'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
          'withdrawals_total', ROUND(v_wd,2), 'operating_result', ROUND(v_res,2),
          'window_days', v_win,
          'threshold', v_th->'withdrawals_vs_profit',
          'period_start', v_w_start, 'period_end', p_period_end,
          'comparison_period_start', NULL, 'comparison_period_end', NULL,
          'sample_size', v_win, 'currency','ARS',
          'source','v_owner_flows + v_finance_pnl',
          'calculation_version', v_ver),
        'action', jsonb_build_object('label','Ver cálculo','target_type','drawer','target','calculation','params', jsonb_build_object()));
    END IF;
  END;

  -- R5. fixed_coverage
  DECLARE
    v_fixed numeric := 0; v_rec_n bigint := 0; v_unconv bigint := 0;
    v_cov numeric;
  BEGIN
    SELECT COUNT(*),
           COALESCE(SUM(CASE
             WHEN COALESCE(re.currency,'ARS') = 'ARS' THEN re.amount
             ELSE re.amount * COALESCE((SELECT er.rate FROM public.exchange_rates er
                                         WHERE er.business_id = v_biz
                                           AND er.base_currency = 'USD'
                                           AND er.target_currency = 'ARS'
                                         ORDER BY er.updated_at DESC LIMIT 1), 0)
           END), 0),
           COUNT(*) FILTER (WHERE COALESCE(re.currency,'ARS') <> 'ARS'
             AND NOT EXISTS (SELECT 1 FROM public.exchange_rates er
                              WHERE er.business_id = v_biz AND er.base_currency='USD'
                                AND er.target_currency='ARS'))
      INTO v_rec_n, v_fixed, v_unconv
      FROM public.recurring_expenses re
     WHERE re.business_id = v_biz AND re.is_active = true;

    IF v_rec_n = 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','fixed_coverage','reason','no_recurring_expenses');
    ELSIF v_unconv > 0 OR v_fixed <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','fixed_coverage','reason','missing_exchange_rate');
    ELSE
      v_cov := ROUND(v_liquidity / NULLIF(v_fixed,0), 2);
      IF v_cov < (v_th->'fixed_coverage'->>'months_warning')::numeric THEN
        v_fired := v_fired || jsonb_build_object(
          'rule_id','fixed_coverage',
          'severity', CASE WHEN v_cov < (v_th->'fixed_coverage'->>'months_critical')::numeric
                           THEN 'critical' ELSE 'warning' END,
          'title','Tu caja cubre poco de los gastos recurrentes',
          'message','Tu caja cubre menos de un mes de los gastos recurrentes que cargaste.',
          'impact_ars', ROUND(v_fixed, 2),
          'evidence', jsonb_build_object(
            'metric','fixed_coverage_months','current_value', v_cov,
            'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
            'cash_total', ROUND(v_liquidity,2), 'fixed_monthly', ROUND(v_fixed,2),
            'recurring_count', v_rec_n,
            'threshold', v_th->'fixed_coverage',
            'period_start', p_period_start, 'period_end', p_period_end,
            'comparison_period_start', NULL, 'comparison_period_end', NULL,
            'sample_size', v_rec_n, 'currency','ARS',
            'source','recurring_expenses + v_finance_position',
            'calculation_version', v_ver),
          'action', jsonb_build_object('label','Ver gastos','target_type','route','target','/expenses','params', jsonb_build_object()));
      END IF;
    END IF;

    -- R6. breakeven_day
    DECLARE
      v_ms date := date_trunc('month', p_period_end)::date;
      v_obs int := (p_period_end - date_trunc('month', p_period_end)::date) + 1;
      v_cm numeric; v_be_sales numeric; v_be_day date; v_daily numeric;
      v_mtd_sales numeric; v_mtd_gp numeric;
    BEGIN
      SELECT COALESCE(SUM(net_sales),0), COALESCE(SUM(gross_profit),0)
        INTO v_mtd_sales, v_mtd_gp
        FROM public.v_finance_pnl
       WHERE business_id = v_biz AND period_date BETWEEN v_ms AND p_period_end;

      v_cm := CASE WHEN v_mtd_sales > 0 THEN v_mtd_gp / v_mtd_sales ELSE NULL END;

      IF v_rec_n = 0 OR v_fixed <= 0 THEN
        v_skipped := v_skipped || jsonb_build_object('rule_id','breakeven_day','reason','no_recurring_expenses');
      ELSIF v_obs < (v_th->'breakeven_day'->>'min_days_observed')::int THEN
        v_skipped := v_skipped || jsonb_build_object('rule_id','breakeven_day','reason','insufficient_days_observed');
      ELSIF v_cm IS NULL OR v_cm <= 0 THEN
        v_skipped := v_skipped || jsonb_build_object('rule_id','breakeven_day','reason','non_positive_contribution_margin');
      ELSE
        v_be_sales := v_fixed / NULLIF(v_cm,0);
        SELECT MIN(d) INTO v_be_day FROM (
          SELECT period_date AS d,
                 SUM(net_sales) OVER (ORDER BY period_date
                                      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum
            FROM public.v_finance_pnl
           WHERE business_id = v_biz AND period_date BETWEEN v_ms AND p_period_end
        ) s WHERE s.cum >= v_be_sales;

        v_daily := v_mtd_sales / NULLIF(v_obs,0);
        IF v_be_day IS NULL THEN
          IF COALESCE(v_daily,0) <= 0 THEN
            v_be_day := NULL;
          ELSE
            v_be_day := v_ms + LEAST(CEIL(v_be_sales / v_daily)::int - 1,
                                     (v_th->'breakeven_day'->>'max_projection_days')::int);
          END IF;
        END IF;

        IF v_be_day IS NULL
           OR (v_be_day - v_ms) > (v_th->'breakeven_day'->>'max_projection_days')::int THEN
          v_skipped := v_skipped || jsonb_build_object('rule_id','breakeven_day','reason','projection_out_of_range');
        ELSE
          v_fired := v_fired || jsonb_build_object(
            'rule_id','breakeven_day','severity','info',
            'title','Punto de equilibrio (estimación)',
            'message','Estimación: según el ritmo de ventas observado, alcanzarías a cubrir los gastos recurrentes cargados dentro del mes en curso.',
            'impact_ars', 0,
            'evidence', jsonb_build_object(
              'metric','breakeven_day','current_value', v_be_day,
              'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
              'is_estimate', true,
              'days_observed', v_obs, 'fixed_monthly', ROUND(v_fixed,2),
              'contribution_margin_pct', ROUND(v_cm * 100, 2),
              'breakeven_sales', ROUND(v_be_sales,2),
              'daily_avg_sales', ROUND(COALESCE(v_daily,0),2),
              'month_to_date_sales', ROUND(v_mtd_sales,2),
              'already_reached', (v_be_day <= p_period_end),
              'threshold', v_th->'breakeven_day',
              'period_start', v_ms, 'period_end', p_period_end,
              'comparison_period_start', NULL, 'comparison_period_end', NULL,
              'sample_size', v_obs, 'currency','ARS',
              'source','v_finance_pnl + recurring_expenses',
              'calculation_version', v_ver),
            'action', jsonb_build_object('label','Ver cálculo','target_type','drawer','target','calculation','params', jsonb_build_object()));
        END IF;
      END IF;
    END;
  END;

  -- R7. supplier_crunch
  DECLARE
    v_overdue numeric := 0; v_due14 numeric := 0; v_undated numeric := 0;
    v_dated_cnt bigint := 0; v_purch_cnt bigint := 0;
    v_near numeric; v_cov numeric; v_min numeric := (v_th->'supplier_crunch'->>'min_material_ars')::numeric;
  BEGIN
    SELECT
      COALESCE(SUM(pending_amount) FILTER (WHERE due_status = 'overdue'), 0),
      COALESCE(SUM(pending_amount) FILTER (WHERE due_status = 'due_soon'), 0),
      COALESCE(SUM(pending_amount) FILTER (WHERE due_status = 'undated'), 0),
      COUNT(*) FILTER (WHERE due_date IS NOT NULL),
      COUNT(*)
      INTO v_overdue, v_due14, v_undated, v_dated_cnt, v_purch_cnt
      FROM public.v_finance_payables_due WHERE business_id = v_biz;

    v_near := v_overdue + v_due14;
    v_cov  := CASE WHEN v_near > 0 THEN ROUND(v_liquidity / v_near, 4) ELSE NULL END;

    IF v_dated_cnt = 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','supplier_crunch','reason','insufficient_due_dates');
    ELSIF v_near < v_min THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','supplier_crunch','reason','below_materiality');
    ELSIF v_near > v_liquidity OR v_cov < (v_th->'supplier_crunch'->>'coverage_warning')::numeric THEN
      v_fired := v_fired || jsonb_build_object(
        'rule_id','supplier_crunch',
        'severity', CASE WHEN v_near > v_liquidity THEN 'critical' ELSE 'warning' END,
        'title','Compromisos con proveedores próximos',
        'message','Hay compromisos con proveedores vencidos o próximos a vencer en el horizonte definido que superan el nivel de cobertura esperado. La deuda sin fecha acordada no se cuenta como compromiso próximo.',
        'impact_ars', ROUND(v_near, 2),
        'evidence', jsonb_build_object(
          'metric','near_term_commitments_coverage',
          'current_value', v_cov, 'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
          'overdue_amount', ROUND(v_overdue,2),
          'due_next_14_days', ROUND(v_due14,2),
          'total_near_term_commitments', ROUND(v_near,2),
          'available_liquidity', ROUND(v_liquidity,2),
          'coverage_ratio', v_cov,
          'purchases_count', v_purch_cnt,
          'dated_purchase_count', v_dated_cnt,
          'dated_pending_amount', ROUND(v_overdue + v_due14, 2),
          'undated_pending_amount', ROUND(v_undated,2),
          'horizon_days', (v_th->'supplier_crunch'->>'horizon_days')::int,
          'threshold', v_th->'supplier_crunch',
          'period_start', v_today, 'period_end', v_today + (v_th->'supplier_crunch'->>'horizon_days')::int,
          'comparison_period_start', NULL, 'comparison_period_end', NULL,
          'sample_size', v_purch_cnt, 'currency','ARS',
          'source','v_finance_payables_due',
          'calculation_version', v_ver),
        'action', jsonb_build_object('label','Ver proveedores','target_type','route','target','/suppliers','params', jsonb_build_object()));
    END IF;
  END;

  -- R8. fx_stale_prices
  DECLARE
    v_rate numeric; v_rate_at timestamptz;
    v_stale bigint := 0; v_usd_tot bigint := 0; v_avg_used numeric;
  BEGIN
    SELECT er.rate, er.updated_at INTO v_rate, v_rate_at
      FROM public.exchange_rates er
     WHERE er.business_id = v_biz AND er.base_currency = 'USD' AND er.target_currency = 'ARS'
     ORDER BY er.updated_at DESC LIMIT 1;

    IF v_rate IS NULL OR v_rate <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','fx_stale_prices','reason','no_reference_rate');
    ELSIF v_rate_at < now() - ((v_th->'fx_stale_prices'->>'max_rate_age_days')::int || ' days')::interval THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','fx_stale_prices','reason','stale_reference_rate');
    ELSE
      SELECT COUNT(*),
             COUNT(*) FILTER (WHERE i.exchange_rate_used IS NOT NULL
               AND i.exchange_rate_used < v_rate * (1 - (v_th->'fx_stale_prices'->>'rate_diff_pct')::numeric / 100)),
             AVG(i.exchange_rate_used)
        INTO v_usd_tot, v_stale, v_avg_used
        FROM public.inventory i
       WHERE i.business_id = v_biz AND i.is_active = true
         AND i.base_currency = 'USD' AND COALESCE(i.base_price,0) > 0;

      IF v_usd_tot = 0 THEN
        v_skipped := v_skipped || jsonb_build_object('rule_id','fx_stale_prices','reason','no_usd_products');
      ELSIF v_stale >= 1
            AND (v_stale::numeric / NULLIF(v_usd_tot,0)) >= (v_th->'fx_stale_prices'->>'share')::numeric THEN
        v_fired := v_fired || jsonb_build_object(
          'rule_id','fx_stale_prices','severity','warning',
          'title','Precios en dólares desactualizados',
          'message','Hay productos en dólares con precios calculados a una cotización anterior a la que tenés cargada hoy.',
          'impact_ars', 0,
          'evidence', jsonb_build_object(
            'metric','stale_usd_price_share',
            'current_value', ROUND(v_stale::numeric / NULLIF(v_usd_tot,0), 4),
            'comparison_value', NULL, 'delta', NULL,
            'delta_percent', ROUND((v_rate - COALESCE(v_avg_used,0)) / NULLIF(v_rate,0) * 100, 2),
            'stale_count', v_stale, 'total_usd_products', v_usd_tot,
            'avg_rate_used', ROUND(COALESCE(v_avg_used,0),4),
            'current_rate', v_rate, 'rate_updated_at', v_rate_at,
            'threshold', v_th->'fx_stale_prices',
            'period_start', p_period_start, 'period_end', p_period_end,
            'comparison_period_start', NULL, 'comparison_period_end', NULL,
            'sample_size', v_usd_tot, 'currency','ARS',
            'source','inventory + exchange_rates',
            'calculation_version', v_ver),
          'action', jsonb_build_object('label','Ver cotización','target_type','route','target','/currency-settings','params', jsonb_build_object()));
      END IF;
    END IF;
  END;

  -- R9. data_quality
  DECLARE
    v_hc jsonb;
    v_crit bigint; v_risk numeric; v_warn bigint; v_low bigint;
  BEGIN
    v_hc := public.finance_health_check_v2(v_biz, false);

    IF COALESCE(v_hc->>'ok','false') <> 'true' THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','data_quality','reason','health_check_unavailable');
    ELSE
      v_crit := COALESCE((v_hc->>'critical_count')::bigint, 0);
      v_risk := COALESCE((v_hc->>'amount_at_risk')::numeric, 0);
      v_warn := COALESCE((v_hc->>'warning_count')::bigint, 0);
      v_low  := COALESCE((v_hc->>'low_count')::bigint, 0);

      IF v_crit < (v_th->'data_quality'->>'critical_count_min')::bigint THEN
        v_skipped := v_skipped || jsonb_build_object('rule_id','data_quality','reason','no_critical_issues');
      ELSE
        v_fired := v_fired || jsonb_build_object(
          'rule_id','data_quality',
          'severity', CASE WHEN v_risk > 0 THEN 'critical' ELSE 'warning' END,
          'title','Hay inconsistencias que pueden distorsionar estos números',
          'message','El chequeo de salud financiera encontró inconsistencias críticas. Mientras existan, los demás números de este panel pueden estar distorsionados.',
          'impact_ars', ROUND(v_risk, 2),
          'evidence', jsonb_build_object(
            'metric','health_critical_count','current_value', v_crit,
            'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
            'critical_count', v_crit, 'amount_at_risk', ROUND(v_risk,2),
            'warning_count', v_warn, 'low_count', v_low,
            'checks_total', COALESCE((v_hc->>'checks_total')::bigint, 0),
            'pass_count', COALESCE((v_hc->>'pass_count')::bigint, 0),
            'overall_status', v_hc->>'overall_status',
            'health_version', v_hc->>'version',
            'threshold', v_th->'data_quality',
            'period_start', p_period_start, 'period_end', p_period_end,
            'comparison_period_start', NULL, 'comparison_period_end', NULL,
            'sample_size', COALESCE((v_hc->>'checks_total')::bigint, 0),
            'currency','ARS','source','finance_health_check_v2',
            'calculation_version', v_ver),
          'action', jsonb_build_object('label','Ver auditoría','target_type','route','target','/finance/health','params', jsonb_build_object()));
      END IF;
    END IF;
  END;

  -- R10. cc_aging
  DECLARE
    v_recv numeric := 0; v_old numeric := 0; v_b3160 numeric := 0; v_b60 numeric := 0;
    v_top_n bigint := 0; v_top_share numeric; v_days int := (v_th->'cc_aging'->>'days')::int;
  BEGIN
    SELECT COALESCE(SUM(amount),0),
           COALESCE(SUM(amount) FILTER (WHERE bucket IN ('31-60','60+')),0),
           COALESCE(SUM(amount) FILTER (WHERE bucket = '31-60'),0),
           COALESCE(SUM(amount) FILTER (WHERE bucket = '60+'),0)
      INTO v_recv, v_old, v_b3160, v_b60
      FROM public.v_finance_receivables_aging WHERE business_id = v_biz;

    IF v_recv <= 0 THEN
      v_skipped := v_skipped || jsonb_build_object('rule_id','cc_aging','reason','no_receivables');
    ELSIF v_old > 0 AND (v_old / NULLIF(v_recv,0)) >= (v_th->'cc_aging'->>'share')::numeric THEN
      WITH per_customer AS (
        SELECT c.customer_id, SUM(c.saldo_pendiente) AS amt
          FROM public.comprobantes c
          JOIN public.v_finance_effective_comprobantes e
            ON e.id = c.id AND e.is_credit_note = false
         WHERE c.business_id = v_biz AND c.saldo_pendiente > 0.01
           AND c.customer_id IS NOT NULL
           AND (v_today - e.period_date) > v_days
         GROUP BY 1
      ), ranked AS (
        SELECT SUM(amt) OVER (ORDER BY amt DESC
                 ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cum,
               SUM(amt) OVER () AS tot,
               ROW_NUMBER() OVER (ORDER BY amt DESC) AS rn
          FROM per_customer
      )
      SELECT COALESCE(MIN(rn), 0),
             COALESCE(ROUND(MIN(cum) / NULLIF(MIN(tot), 0), 4), 0)
        INTO v_top_n, v_top_share
        FROM ranked
       WHERE cum >= tot * (v_th->'cc_aging'->>'concentration_share')::numeric;

      v_fired := v_fired || jsonb_build_object(
        'rule_id','cc_aging','severity','warning',
        'title','Parte de tu cuenta corriente tiene mucha antigüedad',
        'message','Parte de los saldos de cuenta corriente supera el umbral de antigüedad definido sobre el total que te deben.',
        'impact_ars', ROUND(v_old, 2),
        'evidence', jsonb_build_object(
          'metric','receivables_aged_share',
          'current_value', ROUND(v_old / NULLIF(v_recv,0), 4),
          'comparison_value', NULL, 'delta', NULL, 'delta_percent', NULL,
          'overdue_30plus', ROUND(v_old,2), 'receivables_total', ROUND(v_recv,2),
          'bucket_31_60', ROUND(v_b3160,2), 'bucket_60plus', ROUND(v_b60,2),
          'top_debtor_count', v_top_n, 'top_debtor_share', v_top_share,
          'days_threshold', v_days,
          'threshold', v_th->'cc_aging',
          'period_start', p_period_start, 'period_end', p_period_end,
          'comparison_period_start', NULL, 'comparison_period_end', NULL,
          'sample_size', v_top_n, 'currency','ARS',
          'source','v_finance_receivables_aging + comprobantes',
          'calculation_version', v_ver),
        'action', jsonb_build_object('label','Ver cuentas corrientes','target_type','route','target','/cuentas','params', jsonb_build_object()));
    ELSE
      v_skipped := v_skipped || jsonb_build_object('rule_id','cc_aging','reason','below_threshold');
    END IF;
  END;

  -- PERSISTENCIA - identica a 216
  INSERT INTO public.finance_insights AS fi (
    business_id, rule_id, rule_version, period_start, period_end,
    severity, title, message, evidence, action, status, impact_ars, fingerprint,
    generated_at, resolved_at, updated_at)
  SELECT
    v_biz, r->>'rule_id', v_ver, p_period_start, p_period_end,
    r->>'severity', r->>'title', r->>'message', r->'evidence', r->'action',
    'active', COALESCE((r->>'impact_ars')::numeric, 0),
    md5(v_biz::text || '|' || (r->>'rule_id') || '|' || v_ver || '|'
        || p_period_start::text || '|' || p_period_end::text),
    now(), NULL, now()
  FROM jsonb_array_elements(v_fired) r
  ON CONFLICT (fingerprint) DO UPDATE SET
    severity     = EXCLUDED.severity,
    title        = EXCLUDED.title,
    message      = EXCLUDED.message,
    evidence     = EXCLUDED.evidence,
    action       = EXCLUDED.action,
    impact_ars   = EXCLUDED.impact_ars,
    status       = 'active',
    resolved_at  = NULL,
    generated_at = now(),
    updated_at   = now();

  SELECT COALESCE(array_agg(r->>'rule_id'), ARRAY[]::text[]) INTO v_keep
    FROM jsonb_array_elements(v_fired) r;

  UPDATE public.finance_insights
     SET status = 'resolved', resolved_at = now(), updated_at = now()
   WHERE business_id = v_biz AND rule_version = v_ver
     AND period_start = p_period_start AND period_end = p_period_end
     AND status = 'active' AND NOT (rule_id = ANY (v_keep));

  RETURN jsonb_build_object(
    'ok', true,
    'business_id', v_biz,
    'period_start', p_period_start,
    'period_end', p_period_end,
    'comparison_period_start', v_cmp_start,
    'comparison_period_end', v_cmp_end,
    'rule_version', v_ver,
    'generated_at', now(),
    'fired_count', jsonb_array_length(v_fired),
    'fired', (SELECT COALESCE(jsonb_agg(r->>'rule_id'), '[]'::jsonb) FROM jsonb_array_elements(v_fired) r),
    'skipped', v_skipped,
    'thresholds', v_th,
    'duration_ms', round(EXTRACT(epoch FROM (clock_timestamp() - v_t0)) * 1000)::int
  );

EXCEPTION
  WHEN OTHERS THEN
    RAISE WARNING 'generate_finance_insights fallo para business % : % (%)', v_biz, SQLERRM, SQLSTATE;
    RETURN jsonb_build_object('ok', false, 'error', 'No se pudo generar el análisis');
END
$function$

CREATE OR REPLACE FUNCTION public.annul_comprobante_atomic(p_comprobante_id uuid, p_mode text, p_motivo text, p_restore_stock boolean, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_tolerance_ars   constant numeric := 1.00;  -- misma tolerancia que el checkout
  c_key_max         constant integer := 200;
  v_actor           uuid := auth.uid();
  v_reason          text := NULLIF(btrim(COALESCE(p_motivo, '')), '');
  v_key             text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_comp            comprobantes%ROWTYPE;
  v_has_access      boolean := false;
  v_request_hash    text;
  v_prev            comprobante_annulments%ROWTYPE;
  v_numero          text;
  v_open_caja_id    uuid;
  v_cobrado         numeric := 0;
  v_commissions     numeric := 0;
  v_cc_net          numeric := 0;
  v_fm_income_total numeric := 0;
  v_account_id      uuid;
  v_fm              record;
  v_item            record;
  v_bfe             record;
  v_new_fm_id       uuid;
  v_new_bfe_id      uuid;
  v_cc_mov_id       uuid;
  v_prev_stock      integer;
  v_new_stock       integer;
  v_mov_id          uuid;
  v_original_fm_ids uuid[] := '{}';
  v_original_cajas  uuid[] := '{}';
  v_fm_reversals    uuid[] := '{}';
  v_bfe_reversals   uuid[] := '{}';
  v_live_pay_ids    uuid[] := '{}';
  v_inv_movs        uuid[] := '{}';
  v_stock_json      jsonb := '[]'::jsonb;
  v_stock_count     integer := 0;
  v_reverted_cogs   numeric := 0;
  v_annulment_id    uuid;
  -- La fecha de la anulacion es un RESULTADO server-side: no se calcula en el
  -- DECLARE ni entra al hash. Solo se asigna cuando la key es NUEVA.
  v_date            date;
  v_in_audit        boolean := false;
  v_ec              text;
BEGIN
  -- ── 1. Autenticacion / validacion de entrada ──────────────────────────────
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code','UNAUTHORIZED', 'error', 'No autenticado');
  END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('void_same_session', 'refund_current_session', 'commercial_annulment') THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
      'error', 'Modo de anulación inválido: ' || COALESCE(p_mode, '(null)'));
  END IF;
  IF v_reason IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
      'error', 'El motivo de la anulación es obligatorio');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR', 'error', 'idempotency_key requerida');
  END IF;
  IF length(v_key) > c_key_max THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
      'error', 'La clave de idempotencia es demasiado larga');
  END IF;

  -- ── 2. Comprobante + ownership (business_id SIEMPRE del comprobante) ──────
  SELECT * INTO v_comp FROM comprobantes WHERE id = p_comprobante_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code','COMPROBANTE_NOT_FOUND', 'error', 'Comprobante no encontrado');
  END IF;
  SELECT (
    EXISTS (SELECT 1 FROM businesses WHERE id = v_comp.business_id AND owner_user_id = v_actor)
    OR EXISTS (SELECT 1 FROM profiles WHERE business_id = v_comp.business_id AND user_id = v_actor AND COALESCE(is_active, true) = true)
  ) INTO v_has_access;
  IF NOT v_has_access THEN
    RETURN jsonb_build_object('ok', false, 'error_code','FORBIDDEN', 'error', 'Sin acceso a este negocio');
  END IF;

  -- ── 3. Hash canonico: SOLO intencion del caller ───────────────────────────
  -- op + negocio + comprobante + modo + restore_stock + motivo normalizado.
  -- NO incluye ar_today()/fecha/actor/estado/saldos/IDs generados -> idempotencia
  -- DURABLE (un retry al dia siguiente con la misma intencion sigue siendo replay).
  v_request_hash := encode(extensions.digest(jsonb_build_object(
    'op','comprobante_annulment', 'business_id', v_comp.business_id, 'comprobante_id', p_comprobante_id,
    'mode', p_mode, 'restore_stock', COALESCE(p_restore_stock, false), 'reason', v_reason)::text, 'sha256'), 'hex');

  -- ── 4. Replay/conflicto ANTES de la fecha y del guard ─────────────────────
  SELECT * INTO v_prev FROM comprobante_annulments
    WHERE business_id = v_comp.business_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_prev.request_hash IS DISTINCT FROM v_request_hash THEN
      RETURN jsonb_build_object('ok', false, 'error_code','IDEMPOTENCY_CONFLICT',
        'error', 'La idempotency_key ya fue usada con parámetros distintos. Generá una key nueva.');
    END IF;
    RETURN jsonb_build_object('ok', true, 'replay', true,
      'annulment_id', v_prev.id, 'mode', v_prev.mode,
      'reverted_cash_ars', v_prev.reverted_cash_ars, 'reverted_cc_ars', v_prev.reverted_cc_ars,
      'reverted_commissions_ars', v_prev.reverted_commissions_ars, 'reverted_cogs_ars', v_prev.reverted_cogs_ars,
      'stock_restored_count', v_prev.stock_restored_count, 'refund_caja_id', v_prev.refund_caja_id);
  END IF;

  -- ── 5. Fecha economica de la anulacion + guard SOLO de ese periodo ────────
  -- El periodo del comprobante original, sus pagos, su stock y su CC NUNCA se
  -- validan ni se reabren: anular hoy una venta de un mes cerrado es valido.
  v_date := public.ar_today();
  BEGIN PERFORM public.assert_period_open(v_comp.business_id, v_date);
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE 'PERIOD_CLOSED%' THEN RETURN jsonb_build_object('ok', false, 'error_code','PERIOD_CLOSED', 'error', SQLERRM);
    ELSIF SQLERRM LIKE 'INVALID_FINANCE_CONTEXT%' THEN RETURN jsonb_build_object('ok', false, 'error_code','INVALID_FINANCE_CONTEXT', 'error', SQLERRM);
    ELSE RAISE; END IF; END;

  -- ── 6. LOCK del comprobante: punto de serializacion de TODA la operacion ──
  SELECT * INTO v_comp FROM comprobantes WHERE id = p_comprobante_id FOR UPDATE;

  -- ── 7. Relectura de la request YA con el lock tomado ──────────────────────
  -- Una sesion concurrente con la MISMA key pudo completar mientras esperabamos:
  -- se releee ANTES de mirar el estado para devolver replay y no ALREADY_ANNULLED.
  SELECT * INTO v_prev FROM comprobante_annulments
    WHERE business_id = v_comp.business_id AND idempotency_key = v_key;
  IF FOUND THEN
    IF v_prev.request_hash IS DISTINCT FROM v_request_hash THEN
      RETURN jsonb_build_object('ok', false, 'error_code','IDEMPOTENCY_CONFLICT',
        'error', 'La idempotency_key ya fue usada con parámetros distintos. Generá una key nueva.');
    END IF;
    RETURN jsonb_build_object('ok', true, 'replay', true,
      'annulment_id', v_prev.id, 'mode', v_prev.mode,
      'reverted_cash_ars', v_prev.reverted_cash_ars, 'reverted_cc_ars', v_prev.reverted_cc_ars,
      'reverted_commissions_ars', v_prev.reverted_commissions_ars, 'reverted_cogs_ars', v_prev.reverted_cogs_ars,
      'stock_restored_count', v_prev.stock_restored_count, 'refund_caja_id', v_prev.refund_caja_id);
  END IF;

  -- ── 8. Estado (con el estado FRESCO del lock) ─────────────────────────────
  IF v_comp.estado = 'anulado' OR v_comp.status = 'cancelled' OR v_comp.estado_comercial = 'anulado'
     OR EXISTS (SELECT 1 FROM comprobante_annulments WHERE comprobante_id = v_comp.id AND status = 'completed') THEN
    RETURN jsonb_build_object('ok', false, 'error_code','ALREADY_ANNULLED', 'error', 'El comprobante ya está anulado');
  END IF;
  IF COALESCE(v_comp.tipo, v_comp.type) = 'nota_credito' THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
      'error', 'Una nota de crédito no se anula por este flujo');
  END IF;
  -- Fiscal: con CAE corresponde Nota de Credito. Politica PRESERVADA tal cual.
  IF v_comp.cae IS NOT NULL OR v_comp.numero_fiscal IS NOT NULL OR v_comp.estado_fiscal = 'emitido' THEN
    RETURN jsonb_build_object('ok', false, 'error_code','REQUIRES_CREDIT_NOTE',
      'error', 'Este comprobante fue autorizado por ARCA. Generá una Nota de Crédito desde el detalle del comprobante.',
      'requiere_nota_credito', true);
  END IF;

  v_numero := COALESCE(v_comp.numero_fiscal, v_comp.number, v_comp.numero, left(v_comp.id::text, 8));

  -- ── 9. Locks deterministas de las filas que vamos a compensar ─────────────
  -- Pagos VIVOS por id (los reemplazados ya fueron compensados por 6F.3).
  PERFORM 1 FROM comprobante_payments
    WHERE comprobante_id = v_comp.id AND business_id = v_comp.business_id AND replaced_at IS NULL
    ORDER BY id FOR UPDATE;
  -- Movimientos de CC originales de esta venta, por id.
  PERFORM 1 FROM account_movements
    WHERE business_id = v_comp.business_id AND reference_type = 'comprobante' AND reference_id = v_comp.id
    ORDER BY id FOR UPDATE;
  -- Inventarios AGRUPADOS por inventory_id y bloqueados por id (nunca en el orden
  -- de los items): dos anulaciones concurrentes no pueden deadlockear.
  IF COALESCE(p_restore_stock, false) THEN
    PERFORM 1 FROM inventory
      WHERE business_id = v_comp.business_id
        AND id IN (SELECT DISTINCT ci.inventory_id FROM comprobante_items ci
                    WHERE ci.comprobante_id = v_comp.id AND ci.stock_processed = true
                      AND ci.inventory_id IS NOT NULL
                      AND COALESCE(ci.tipo_linea,'producto') IN ('producto','repuesto'))
      ORDER BY id FOR UPDATE;
  END IF;

  -- ── 10. Medir lo REALMENTE registrado y VIGENTE (nunca total_bruto) ───────
  SELECT COALESCE(SUM(amount_ars), 0), COALESCE(SUM(commission_amount), 0), COALESCE(array_agg(id ORDER BY id), '{}')
    INTO v_cobrado, v_commissions, v_live_pay_ids
    FROM comprobante_payments
    WHERE comprobante_id = v_comp.id AND business_id = v_comp.business_id AND replaced_at IS NULL;

  SELECT COALESCE(SUM(debit - credit), 0) INTO v_cc_net
    FROM account_movements
    WHERE business_id = v_comp.business_id
      AND reference_type = 'comprobante' AND reference_id = v_comp.id;

  -- FM de ingreso VIGENTES: reversed_at IS NULL excluye los ingresos ya
  -- compensados por un reemplazo de cobro previo (6F.3). Sin este filtro la
  -- anulacion devolvia el eslabon viejo Y el nuevo -> caja negativa.
  SELECT COALESCE(SUM(amount_ars), 0),
         COALESCE(array_agg(id ORDER BY id), '{}'),
         COALESCE(array_agg(DISTINCT caja_id) FILTER (WHERE caja_id IS NOT NULL), '{}')
    INTO v_fm_income_total, v_original_fm_ids, v_original_cajas
    FROM financial_movements
    WHERE comprobante_id = v_comp.id AND business_id = v_comp.business_id
      AND type = 'income' AND COALESCE(sign, 1) = 1 AND reversed_at IS NULL;

  SELECT id INTO v_open_caja_id FROM cajas
    WHERE business_id = v_comp.business_id AND status = 'abierta'
    ORDER BY opened_at DESC LIMIT 1;

  -- ── 11. Validaciones por modo (politica comercial PRESERVADA) ─────────────
  IF p_mode = 'commercial_annulment' THEN
    IF v_cobrado > c_tolerance_ars THEN
      RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
        'error', format('Este comprobante tiene $%s cobrados. Si devolviste el dinero usá el modo devolución; si no, no corresponde anulación comercial.', round(v_cobrado, 2)));
    END IF;
  ELSE
    IF v_cobrado <= c_tolerance_ars AND v_fm_income_total <= c_tolerance_ars THEN
      RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
        'error', 'No hay cobros registrados para devolver — usá la anulación comercial (sin devolución de dinero).');
    END IF;
    IF v_open_caja_id IS NULL THEN
      RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
        'error', 'No hay caja abierta. Abrí una caja para registrar la devolución.');
    END IF;
    IF p_mode = 'void_same_session' THEN
      IF EXISTS (
        SELECT 1 FROM financial_movements
        WHERE comprobante_id = v_comp.id AND business_id = v_comp.business_id
          AND type = 'income' AND COALESCE(sign, 1) = 1 AND reversed_at IS NULL
          AND (caja_id IS DISTINCT FROM v_open_caja_id)
      ) THEN
        RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR',
          'error', 'La venta no pertenece a la caja abierta actual — usá el modo devolución (el egreso se registra en la caja de hoy sin tocar la sesión original).');
      END IF;
    END IF;
  END IF;

  -- ── 12. Audit scope E1: a partir de aca escribimos tablas con backstop ────
  PERFORM public.finance_begin_audit_scope();

  -- ── 13. Compensacion de caja: UN egreso espejo por CADA ingreso VIGENTE ───
  FOR v_fm IN
    SELECT * FROM financial_movements
    WHERE comprobante_id = v_comp.id AND business_id = v_comp.business_id
      AND type = 'income' AND COALESCE(sign, 1) = 1 AND reversed_at IS NULL
    ORDER BY id
  LOOP
    INSERT INTO financial_movements (
      business_id, date, type, currency, amount, amount_ars, exchange_rate,
      source, source_id, comprobante_id, description, created_by, sign,
      metodo_pago, caja_id, reference_type, reference_id, movement_type
    ) VALUES (
      v_comp.business_id, v_date, 'expense',
      v_fm.currency, v_fm.amount, v_fm.amount_ars, COALESCE(v_fm.exchange_rate, 1),
      'comprobante', v_fm.source_id, v_comp.id,
      'ANULACIÓN Comprobante #' || v_numero || ' — reversa de mov. ' || v_fm.id || ' · ' || v_reason,
      v_actor, -1,
      v_fm.metodo_pago, v_open_caja_id, 'annulment_reversal', v_fm.id, 'refund'
    ) RETURNING id INTO v_new_fm_id;
    v_fm_reversals := v_fm_reversals || v_new_fm_id;
  END LOOP;

  -- ── 14. Espejos negativos de BFE (trazabilidad; el P&L NO los lee) ────────
  -- La reversion devengada de venta/COGS la DERIVA v_finance_sales_ledger desde
  -- comprobante_annulments. Estos espejos se conservan como trazabilidad y para
  -- la comision (payment_fee), que si es un gasto real del P&L y debe revertirse.
  FOR v_bfe IN
    SELECT * FROM business_finance_entries
    WHERE business_id = v_comp.business_id
      AND reference_comprobante_id = v_comp.id
      AND amount_ars > 0
      AND (type = 'income' OR (type = 'variable_cost' AND category IN ('comisiones_cobro', 'mercaderia')))
    ORDER BY created_at
  LOOP
    INSERT INTO business_finance_entries (
      business_id, date, type, category, description,
      amount, currency, amount_ars, exchange_rate,
      payment_method, reference_comprobante_id, source, created_by
    ) VALUES (
      v_comp.business_id, v_date, v_bfe.type, v_bfe.category,
      'ANULACIÓN Comprobante #' || v_numero || ' — reversa de asiento ' || v_bfe.id,
      -v_bfe.amount, v_bfe.currency, -v_bfe.amount_ars, COALESCE(v_bfe.exchange_rate, 1),
      v_bfe.payment_method, v_comp.id, 'annulment', v_actor
    ) RETURNING id INTO v_new_bfe_id;
    v_bfe_reversals := v_bfe_reversals || v_new_bfe_id;
    IF v_bfe.type = 'variable_cost' AND v_bfe.category = 'mercaderia' THEN
      v_reverted_cogs := v_reverted_cogs + v_bfe.amount_ars;
    END IF;
  END LOOP;

  -- COGS historico sin referencia (BFE de checkouts anteriores a 20260702110000).
  FOR v_bfe IN
    SELECT * FROM business_finance_entries
    WHERE business_id = v_comp.business_id
      AND reference_comprobante_id IS NULL
      AND type = 'variable_cost' AND category = 'mercaderia'
      AND amount_ars > 0
      AND description = 'Costo de productos - Comprobante #' || v_numero
    ORDER BY created_at
  LOOP
    INSERT INTO business_finance_entries (
      business_id, date, type, category, description,
      amount, currency, amount_ars, exchange_rate,
      reference_comprobante_id, source, created_by
    ) VALUES (
      v_comp.business_id, v_date, 'variable_cost', 'mercaderia',
      'ANULACIÓN Comprobante #' || v_numero || ' — reversa de asiento ' || v_bfe.id,
      -v_bfe.amount, v_bfe.currency, -v_bfe.amount_ars, COALESCE(v_bfe.exchange_rate, 1),
      v_comp.id, 'annulment', v_actor
    ) RETURNING id INTO v_new_bfe_id;
    v_bfe_reversals := v_bfe_reversals || v_new_bfe_id;
    v_reverted_cogs := v_reverted_cogs + v_bfe.amount_ars;
  END LOOP;

  -- ── 15. Cuenta corriente: movimiento contrario HOY (historico intacto) ────
  IF v_cc_net > 0.01 THEN
    SELECT account_id INTO v_account_id
      FROM account_movements
      WHERE business_id = v_comp.business_id
        AND reference_type = 'comprobante' AND reference_id = v_comp.id
      ORDER BY created_at LIMIT 1;
    IF v_account_id IS NOT NULL THEN
      INSERT INTO account_movements (
        business_id, account_id, date, type, description, debit, credit,
        reference_type, reference_id, created_by
      ) VALUES (
        v_comp.business_id, v_account_id, v_date, 'ajuste',
        'ANULACIÓN Comprobante #' || v_numero || ' · ' || v_reason,
        0, v_cc_net, 'comprobante', v_comp.id, v_actor
      ) RETURNING id INTO v_cc_mov_id;
    END IF;
  END IF;

  -- ── 16. Stock: append-only, agrupado por inventory_id, cantidades enteras ─
  IF COALESCE(p_restore_stock, false) THEN
    FOR v_item IN
      SELECT ci.inventory_id, SUM(ci.cantidad)::integer AS cantidad
      FROM comprobante_items ci
      WHERE ci.comprobante_id = v_comp.id
        AND ci.stock_processed = true
        AND ci.inventory_id IS NOT NULL
        AND COALESCE(ci.tipo_linea, 'producto') IN ('producto', 'repuesto')
      GROUP BY ci.inventory_id
      ORDER BY ci.inventory_id
    LOOP
      SELECT stock_quantity INTO v_prev_stock FROM inventory
        WHERE id = v_item.inventory_id AND business_id = v_comp.business_id;
      IF FOUND THEN
        v_prev_stock := COALESCE(v_prev_stock, 0);
        v_new_stock  := v_prev_stock + v_item.cantidad;
        UPDATE inventory SET stock_quantity = v_new_stock, updated_at = now()
          WHERE id = v_item.inventory_id AND business_id = v_comp.business_id;
        INSERT INTO inventory_movements (
          business_id, inventory_item_id, movement_type, quantity, previous_stock,
          new_stock, reference_type, reference_id, note, created_by
        ) VALUES (
          v_comp.business_id, v_item.inventory_id, 'return',
          v_item.cantidad, v_prev_stock, v_new_stock,
          'comprobante', v_comp.id,
          'Devolución por anulación de comprobante #' || v_numero, v_actor
        ) RETURNING id INTO v_mov_id;
        v_inv_movs   := v_inv_movs || v_mov_id;
        v_stock_json := v_stock_json || jsonb_build_object(
          'inventory_id', v_item.inventory_id, 'qty', v_item.cantidad,
          'prev_stock', v_prev_stock, 'new_stock', v_new_stock, 'movement_id', v_mov_id);
        v_stock_count := v_stock_count + 1;
      END IF;
    END LOOP;
    -- Marcador exactamente-una-vez sobre TODAS las lineas procesadas.
    UPDATE comprobante_items
      SET stock_processed = false, stock_processed_at = NULL, stock_movement_id = NULL
      WHERE comprobante_id = v_comp.id AND stock_processed = true;
  END IF;

  -- ── 17. Metadata OPERATIVA del comprobante ───────────────────────────────
  -- Solo estado + rastro de anulacion. Fecha, numero, punto de venta, tipo,
  -- moneda, totales, cliente, orden, condicion fiscal, CAE y su vencimiento
  -- NO se tocan: el comprobante sigue siendo el mismo documento.
  PERFORM set_config('m7.annulment_scope', '1', true);
  UPDATE comprobantes SET
    estado           = 'anulado',
    status           = 'cancelled',
    estado_comercial = 'anulado',
    estado_fiscal    = CASE WHEN estado_fiscal = 'no_fiscal' THEN 'no_fiscal' ELSE 'anulado_fiscal' END,
    afip_response    = COALESCE(afip_response, '{}'::jsonb) || jsonb_build_object(
                         'anulacion', jsonb_build_object(
                           'motivo', v_reason, 'modo', p_mode,
                           'restore_stock', COALESCE(p_restore_stock, false), 'fecha', v_date)),
    updated_at       = now()
  WHERE id = v_comp.id;

  -- ── 18. Registro canonico (idempotencia + fuente del evento devengado) ────
  INSERT INTO comprobante_annulments (
    business_id, comprobante_id, user_id, idempotency_key, request_hash, op,
    mode, motivo, restore_stock, stock_restored_count, annulment_date,
    original_caja_ids, refund_caja_id,
    reverted_cash_ars, reverted_cc_ars, reverted_commissions_ars, reverted_cogs_ars,
    original_fm_ids, fm_reversal_ids, bfe_reversal_ids, cc_reversal_movement_id
  ) VALUES (
    v_comp.business_id, v_comp.id, v_actor, v_key, v_request_hash, 'comprobante_annulment',
    p_mode, v_reason, COALESCE(p_restore_stock, false), v_stock_count, v_date,
    v_original_cajas, v_open_caja_id,
    GREATEST(v_cobrado, v_fm_income_total), v_cc_net, v_commissions, v_reverted_cogs,
    v_original_fm_ids, v_fm_reversals, v_bfe_reversals, v_cc_mov_id
  ) RETURNING id INTO v_annulment_id;

  -- ── 19. UN unico evento de auditoria ─────────────────────────────────────
  v_in_audit := true;
  PERFORM finance_log_audit(
    v_comp.business_id, 'comprobante_annulment', 'comprobantes', v_comp.id, 'annul_comprobante_atomic',
    v_key, v_reason, v_date, 'comprobante', v_comp.id,
    NULL, jsonb_build_object(
      'comprobante_id', v_comp.id, 'annulment_id', v_annulment_id, 'numero', v_numero,
      'reason', v_reason, 'mode', p_mode,
      'original_date', (COALESCE(v_comp.fecha, v_comp.date, v_comp.created_at) AT TIME ZONE 'America/Argentina/Cordoba')::date,
      'annulment_date', v_date,
      'original_period', to_char((COALESCE(v_comp.fecha, v_comp.date, v_comp.created_at) AT TIME ZONE 'America/Argentina/Cordoba')::date, 'YYYY-MM'),
      'annulment_period', to_char(v_date, 'YYYY-MM'),
      'customer_id', v_comp.customer_id, 'order_id', v_comp.order_id, 'sale_total', v_comp.total,
      'reverted_cash_ars', GREATEST(v_cobrado, v_fm_income_total), 'reverted_cc_ars', v_cc_net,
      'reverted_commissions_ars', v_commissions, 'reverted_cogs_ars', v_reverted_cogs,
      'live_payment_ids', to_jsonb(v_live_pay_ids),
      'original_fm_ids', to_jsonb(v_original_fm_ids), 'fm_reversal_ids', to_jsonb(v_fm_reversals),
      'bfe_reversal_ids', to_jsonb(v_bfe_reversals), 'cc_reversal_movement_id', v_cc_mov_id,
      'stock_restored', v_stock_json, 'inventory_movement_ids', to_jsonb(v_inv_movs),
      'original_caja_ids', to_jsonb(v_original_cajas), 'refund_caja_id', v_open_caja_id,
      'actor', v_actor, 'request_hash', v_request_hash));
  v_in_audit := false;

  RETURN jsonb_build_object(
    'ok', true, 'replay', false,
    'annulment_id', v_annulment_id, 'mode', p_mode,
    'reverted_cash_ars', GREATEST(v_cobrado, v_fm_income_total),
    'reverted_cc_ars', v_cc_net,
    'reverted_commissions_ars', v_commissions,
    'reverted_cogs_ars', v_reverted_cogs,
    'stock_restored_count', v_stock_count,
    'refund_caja_id', v_open_caja_id
  );

EXCEPTION WHEN OTHERS THEN
  -- Rollback TOTAL al savepoint implicito: nunca queda una anulacion a medias
  -- (ni compensacion parcial, ni request huerfana, ni auditoria parcial).
  v_ec := CASE
    WHEN v_in_audit THEN 'AUDIT_FAILED'
    WHEN SQLSTATE = '23505' THEN 'IDEMPOTENCY_CONFLICT'
    ELSE 'INTERNAL_ERROR' END;
  IF v_ec = 'IDEMPOTENCY_CONFLICT' THEN
    RETURN jsonb_build_object('ok', false, 'error_code','IDEMPOTENCY_CONFLICT',
      'error', 'La idempotency_key ya fue usada con parámetros distintos. Generá una key nueva.');
  END IF;
  RETURN jsonb_build_object('ok', false, 'error_code', v_ec,
    'error', CASE WHEN v_ec='AUDIT_FAILED' THEN 'No se pudo registrar la auditoria de la operacion'
                  ELSE 'No se pudo completar la operacion' END);
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_recurring_expense(p_expense_id uuid, p_account_id uuid, p_amount numeric, p_paid_date date, p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_user_id    uuid := auth.uid();
  v_expense    public.personal_recurring_expenses%rowtype;
  v_account    public.personal_accounts%rowtype;
  v_tx_id      uuid;
  v_payment_id uuid;
  v_period_y   int  := extract(year  from p_paid_date)::int;
  v_period_m   int  := extract(month from p_paid_date)::int;
  v_next_due   date;
  v_cat_id     uuid;
BEGIN
  SELECT * INTO v_expense FROM public.personal_recurring_expenses
   WHERE id = p_expense_id AND user_id = v_user_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'NOT_FOUND', 'error', 'Gasto fijo no encontrado');
  END IF;
  IF v_expense.status = 'cancelled' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', 'El gasto fijo está cancelado');
  END IF;
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', 'El monto debe ser mayor a $0');
  END IF;

  SELECT * INTO v_account FROM public.personal_accounts
   WHERE id = p_account_id AND user_id = v_user_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'NOT_FOUND', 'error', 'Cuenta no encontrada');
  END IF;

  -- Atajo barato. La garantía de verdad es la UNIQUE de más abajo: entre este
  -- chequeo y el INSERT hay una ventana en la que otra sesión puede insertar.
  IF EXISTS (
    SELECT 1 FROM public.personal_recurring_expense_payments
     WHERE recurring_expense_id = p_expense_id
       AND period_year = v_period_y AND period_month = v_period_m
  ) THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'ALREADY_PAID',
      'error', 'Ya se registró un pago para este mes');
  END IF;

  v_cat_id := v_expense.category_id;
  IF v_cat_id IS NULL THEN
    SELECT id INTO v_cat_id FROM public.personal_categories
     WHERE user_id = v_user_id AND type = 'expense'
       AND (lower(name) LIKE '%servicio%' OR lower(name) LIKE '%fijo%'
            OR lower(name) LIKE '%gasto%' OR lower(name) LIKE '%hogar%')
     LIMIT 1;
  END IF;

  INSERT INTO public.personal_transactions (
    user_id, account_id, category_id, type, amount, currency,
    date, description, notes, payment_method, linked_owner_withdrawal_id
  ) VALUES (
    v_user_id, p_account_id, v_cat_id, 'expense', p_amount, v_expense.currency,
    p_paid_date, 'Gasto fijo: ' || v_expense.name, p_notes, NULL, NULL
  ) RETURNING id INTO v_tx_id;

  PERFORM public.personal_update_currency_balance(p_account_id, v_expense.currency, -p_amount);

  INSERT INTO public.personal_recurring_expense_payments (
    user_id, recurring_expense_id, account_id, transaction_id,
    currency, amount, paid_date, period_year, period_month, notes
  ) VALUES (
    v_user_id, p_expense_id, p_account_id, v_tx_id,
    v_expense.currency, p_amount, p_paid_date, v_period_y, v_period_m, p_notes
  ) RETURNING id INTO v_payment_id;

  IF v_expense.due_day IS NOT NULL THEN
    v_next_due := (date_trunc('month', p_paid_date + interval '1 month')
                   + (v_expense.due_day - 1) * interval '1 day')::date;
    v_next_due := least(v_next_due,
      (date_trunc('month', p_paid_date + interval '1 month') + interval '1 month - 1 day')::date);
    UPDATE public.personal_recurring_expenses SET next_due_date = v_next_due WHERE id = p_expense_id;
  END IF;

  RETURN jsonb_build_object('ok', true, 'payment_id', v_payment_id,
    'transaction_id', v_tx_id, 'next_due_date', v_next_due);

EXCEPTION
  -- Perdió la carrera contra otra sesión del mismo período. Todo el cuerpo se
  -- revierte (transacción y débito incluidos), así que el efecto económico
  -- ocurre UNA sola vez. Antes esto devolvía el texto crudo de la constraint.
  WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'ALREADY_PAID',
      'error', 'Ya se registró un pago para este mes');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'INTERNAL_ERROR',
      'error', 'No se pudo registrar el pago del gasto fijo');
END; $function$

CREATE OR REPLACE FUNCTION public.allocate_account_payment_atomic(p_business_id uuid, p_payment_movement_id uuid, p_allocations jsonb, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_actor    uuid := auth.uid();
  v_key      text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_mov      public.account_movements%ROWTYPE;
  v_acc_cus  uuid;
  v_item     jsonb;
  v_ids      uuid[] := '{}';
  v_total    numeric := 0;
  v_new_id   uuid;
  v_i        integer := 0;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'UNAUTHORIZED', 'error', 'No autenticado');
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', 'idempotency_key requerida');
  END IF;
  IF p_allocations IS NULL OR jsonb_array_length(p_allocations) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', 'Sin asignaciones');
  END IF;

  -- CAPACIDAD, no sólo pertenencia: tech y viewer no imputan.
  IF NOT public.user_can_allocate_payments(p_business_id, v_actor) THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'FORBIDDEN',
      'error', 'Tu rol no puede imputar cobros');
  END IF;

  IF EXISTS (SELECT 1 FROM public.customer_account_payment_allocations
              WHERE business_id = p_business_id
                AND left(idempotency_key, length(v_key) + 1) = v_key || ':') THEN
    SELECT COALESCE(array_agg(id ORDER BY created_at), '{}'), COALESCE(SUM(amount), 0)
      INTO v_ids, v_total
      FROM public.customer_account_payment_allocations
     WHERE business_id = p_business_id
       AND left(idempotency_key, length(v_key) + 1) = v_key || ':'
       AND status = 'active';
    RETURN jsonb_build_object('ok', true, 'replay', true,
      'allocation_ids', to_jsonb(v_ids), 'allocated_total', v_total);
  END IF;

  SELECT * INTO v_mov FROM public.account_movements
   WHERE id = p_payment_movement_id AND business_id = p_business_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'PAYMENT_NOT_FOUND', 'error', 'Cobro no encontrado');
  END IF;
  SELECT entity_id INTO v_acc_cus FROM public.accounts WHERE id = v_mov.account_id;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_allocations)
  LOOP
    v_i := v_i + 1;
    INSERT INTO public.customer_account_payment_allocations (
      business_id, customer_id, account_id, payment_movement_id, comprobante_id,
      amount, currency, status, idempotency_key, reason, created_by
    ) VALUES (
      p_business_id, v_acc_cus, v_mov.account_id, p_payment_movement_id,
      (v_item->>'comprobante_id')::uuid,
      ROUND((v_item->>'amount')::numeric, 2), 'ARS', 'active',
      v_key || ':' || v_i, NULLIF(btrim(COALESCE(p_reason, '')), ''), v_actor
    ) RETURNING id INTO v_new_id;
    v_ids   := v_ids || v_new_id;
    v_total := v_total + ROUND((v_item->>'amount')::numeric, 2);
  END LOOP;

  PERFORM public.finance_log_audit(
    p_business_id, 'account_payment_allocated', 'account_movements', p_payment_movement_id,
    'allocate_account_payment_atomic', v_key, p_reason, public.ar_today(),
    'account_movement', p_payment_movement_id, NULL,
    jsonb_build_object('payment_movement_id', p_payment_movement_id,
      'allocation_ids', to_jsonb(v_ids), 'allocated_total', v_total, 'items', p_allocations));

  RETURN jsonb_build_object('ok', true, 'replay', false,
    'allocation_ids', to_jsonb(v_ids), 'allocated_total', v_total);

EXCEPTION
  WHEN sqlstate '22023' OR sqlstate '42501' OR sqlstate '23503' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', SQLERRM);
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'INTERNAL_ERROR',
      'error', 'No se pudo completar la imputación');
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_payment_allocation_atomic(p_business_id uuid, p_allocation_id uuid, p_amount numeric, p_reason text, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_actor  uuid := auth.uid();
  v_key    text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_reason text := NULLIF(btrim(COALESCE(p_reason, '')), '');
  v_al     public.customer_account_payment_allocations%ROWTYPE;
  v_rev    numeric;
  v_rem    numeric;
  v_new    uuid;
BEGIN
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'UNAUTHORIZED', 'error', 'No autenticado');
  END IF;
  IF v_key IS NULL OR v_reason IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR',
      'error', 'idempotency_key y motivo son obligatorios');
  END IF;

  -- Revertir es más restrictivo que imputar: deshace un hecho ya asentado.
  IF NOT public.user_can_reverse_allocations(p_business_id, v_actor) THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'FORBIDDEN',
      'error', 'Tu rol no puede revertir imputaciones');
  END IF;

  IF EXISTS (SELECT 1 FROM public.customer_account_payment_allocations
              WHERE business_id = p_business_id AND idempotency_key = v_key) THEN
    RETURN jsonb_build_object('ok', true, 'replay', true);
  END IF;

  SELECT * INTO v_al FROM public.customer_account_payment_allocations
   WHERE id = p_allocation_id AND business_id = p_business_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'ALLOCATION_NOT_FOUND', 'error', 'Imputación no encontrada');
  END IF;
  IF v_al.status <> 'active' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'ALREADY_REVERSED', 'error', 'La imputación ya fue revertida');
  END IF;

  v_rev := COALESCE(ROUND(p_amount, 2), v_al.amount);
  IF v_rev <= 0 OR v_rev > v_al.amount + 0.01 THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR',
      'error', 'El importe a revertir debe estar entre 0 y el importe imputado');
  END IF;

  UPDATE public.customer_account_payment_allocations
     SET status = 'reversed', reversed_at = now()
   WHERE id = v_al.id;

  v_rem := ROUND(v_al.amount - v_rev, 2);
  IF v_rem > 0 THEN
    INSERT INTO public.customer_account_payment_allocations (
      business_id, customer_id, account_id, payment_movement_id, comprobante_id,
      amount, currency, status, idempotency_key, reason, reversal_of, created_by
    ) VALUES (
      v_al.business_id, v_al.customer_id, v_al.account_id, v_al.payment_movement_id,
      v_al.comprobante_id, v_rem, 'ARS', 'active', v_key || ':rem',
      'Remanente tras reversa parcial', v_al.id, v_actor
    ) RETURNING id INTO v_new;
  END IF;

  INSERT INTO public.customer_account_payment_allocations (
    business_id, customer_id, account_id, payment_movement_id, comprobante_id,
    amount, currency, status, idempotency_key, reason, reversal_of, reversed_at, created_by
  ) VALUES (
    v_al.business_id, v_al.customer_id, v_al.account_id, v_al.payment_movement_id,
    v_al.comprobante_id, v_rev, 'ARS', 'reversed', v_key, v_reason, v_al.id, now(), v_actor);

  PERFORM public.finance_log_audit(
    p_business_id, 'account_payment_allocation_reversed', 'customer_account_payment_allocations',
    v_al.id, 'reverse_payment_allocation_atomic', v_key, v_reason, public.ar_today(),
    'allocation', v_al.id, NULL,
    jsonb_build_object('allocation_id', v_al.id, 'comprobante_id', v_al.comprobante_id,
      'reversed_amount', v_rev, 'remaining_allocation_id', v_new, 'remaining_amount', v_rem));

  PERFORM public.recompute_order_payment_status(
    (SELECT order_id FROM public.comprobantes WHERE id = v_al.comprobante_id));

  RETURN jsonb_build_object('ok', true, 'replay', false,
    'reversed_amount', v_rev, 'remaining_amount', v_rem, 'remaining_allocation_id', v_new);

EXCEPTION
  WHEN sqlstate '22023' OR sqlstate '42501' OR sqlstate '0A000' THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', SQLERRM);
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'INTERNAL_ERROR',
      'error', 'No se pudo completar la reversa');
END;
$function$

CREATE OR REPLACE FUNCTION private.finance_health_check_v2(p_business_id uuid DEFAULT NULL::uuid, p_include_global boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_t0      timestamptz := clock_timestamp();
  v_actor   uuid := auth.uid();
  v_biz     uuid := p_business_id;
  v_access  boolean := false;
  v_c       jsonb := '[]'::jsonb;   -- acumulador de checks
  n         bigint;
  m         numeric;
  d         jsonb;
  v_has_ledger  boolean := to_regclass('public.v_finance_sales_ledger') IS NOT NULL;
  v_has_audit   boolean := to_regclass('public.finance_audit_log') IS NOT NULL;
  v_has_locks   boolean := to_regclass('public.finance_period_locks') IS NOT NULL;
  v_has_recon   boolean := to_regclass('public.finance_ledger_reconciliation') IS NOT NULL;
  v_has_repl    boolean := EXISTS(SELECT 1 FROM information_schema.columns
                                   WHERE table_name='comprobante_payments' AND column_name='replaced_at');
  v_has_anndate boolean := EXISTS(SELECT 1 FROM information_schema.columns
                                   WHERE table_name='comprobante_annulments' AND column_name='annulment_date');
BEGIN
  -- ── Autenticacion y aislamiento por negocio ───────────────────────────────
  IF v_actor IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'No autenticado');
  END IF;
  IF v_biz IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'business_id requerido');
  END IF;
  SELECT (EXISTS (SELECT 1 FROM businesses WHERE id=v_biz AND owner_user_id=v_actor)
       OR EXISTS (SELECT 1 FROM profiles WHERE business_id=v_biz AND COALESCE(user_id,id)=v_actor
                    AND COALESCE(is_active,true))) INTO v_access;
  IF NOT v_access THEN
    RETURN jsonb_build_object('ok', false, 'error', 'Sin acceso a este negocio');
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: periods
  -- ══════════════════════════════════════════════════════════════════════════
  IF v_has_locks THEN
    SELECT count(*) INTO n FROM finance_period_locks a JOIN finance_period_locks b
      ON a.business_id=b.business_id AND a.id<>b.id AND a.status='closed' AND b.status='closed'
     AND a.period_start <= b.period_end AND b.period_start <= a.period_end
     WHERE a.business_id=v_biz;
    v_c := v_c || finance_hc_mk('period_locks_overlapping','periods','Períodos cerrados superpuestos',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Sin solapamientos entre períodos cerrados'
           ELSE n||' par(es) de períodos cerrados se superponen: una fecha puede caer en dos locks' END);

    SELECT count(*) INTO n FROM finance_period_locks
     WHERE business_id=v_biz AND reopened_at IS NOT NULL AND COALESCE(btrim(reopen_reason),'')='';
    v_c := v_c || finance_hc_mk('period_reopened_without_reason','periods','Reaperturas sin motivo',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Toda reapertura tiene motivo' ELSE n||' reapertura(s) sin motivo documentado' END);

    SELECT count(*) INTO n FROM finance_period_locks
     WHERE business_id=v_biz AND reopened_at IS NOT NULL AND closed_at IS NOT NULL AND reopened_at < closed_at;
    v_c := v_c || finance_hc_mk('period_reopen_out_of_order','periods','Reapertura anterior al cierre',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Cierres y reaperturas en orden' ELSE n||' período(s) reabiertos antes de cerrarse' END);

    -- Escrituras economicas fechadas DENTRO de un periodo cerrado pero creadas
    -- DESPUES del cierre. Una compensacion de HOY que referencia un asiento de
    -- un periodo cerrado NO cuenta: su `date` es de hoy, no del período cerrado.
    SELECT count(*), COALESCE(SUM(f.amount_ars),0) INTO n, m
      FROM financial_movements f JOIN finance_period_locks l
        ON l.business_id=f.business_id AND l.status='closed'
       AND (f.date AT TIME ZONE 'America/Argentina/Cordoba')::date BETWEEN l.period_start AND l.period_end
     WHERE f.business_id=v_biz AND f.created_at > l.closed_at;
    v_c := v_c || finance_hc_mk('writes_after_period_close','periods','Escrituras dentro de un período cerrado',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
      CASE WHEN n=0 THEN 'Ningún movimiento se escribió dentro de un período ya cerrado'
           ELSE n||' movimiento(s) fechados en un período cerrado fueron creados DESPUÉS del cierre' END);
  END IF;

  SELECT count(*) INTO n FROM financial_movements WHERE business_id=v_biz AND date IS NULL;
  v_c := v_c || finance_hc_mk('entities_null_economic_date','periods','Movimientos sin fecha económica',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Toda entidad económica tiene fecha' ELSE n||' movimiento(s) sin fecha económica' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: audit
  -- ══════════════════════════════════════════════════════════════════════════
  IF v_has_audit THEN
    SELECT count(*) INTO n FROM finance_audit_log WHERE business_id=v_biz AND actor_user_id IS NULL;
    v_c := v_c || finance_hc_mk('audit_without_actor','audit','Eventos de auditoría sin actor',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Todo evento tiene actor' ELSE n||' evento(s) sin actor' END);

    SELECT count(*) INTO n FROM finance_audit_log l
     WHERE l.business_id=v_biz AND l.entity_table='comprobantes'
       AND NOT EXISTS (SELECT 1 FROM comprobantes c WHERE c.id=l.entity_id);
    v_c := v_c || finance_hc_mk('audit_entity_missing','audit','Eventos que apuntan a entidades inexistentes',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Todas las referencias de auditoría resuelven' ELSE n||' evento(s) apuntan a un comprobante inexistente' END);

    SELECT count(*) INTO n FROM finance_audit_log l JOIN comprobantes c ON c.id=l.entity_id
     WHERE l.business_id=v_biz AND l.entity_table='comprobantes' AND c.business_id <> l.business_id;
    v_c := v_c || finance_hc_mk('audit_cross_business','audit','Auditoría cross-business',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Sin referencias cross-business en la auditoría' ELSE n||' evento(s) referencian entidades de otro negocio' END);

    -- Una anulacion canonica DEBE tener su evento explicito (uno solo).
    SELECT count(*) INTO n FROM comprobante_annulments a
     WHERE a.business_id=v_biz AND a.status='completed'
       AND NOT EXISTS (SELECT 1 FROM finance_audit_log l
                        WHERE l.entity_id=a.comprobante_id AND l.source_rpc='annul_comprobante_atomic');
    v_c := v_c || finance_hc_mk('annulment_without_audit_event','audit','Anulaciones sin evento de auditoría',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Toda anulación canónica tiene su evento'
           ELSE n||' anulación(es) sin evento. Las reconciliaciones históricas (7B) y las anulaciones M6 previas a M7 no lo tienen: revisar contra finance_ledger_reconciliation' END);

    SELECT count(*) INTO n FROM (
      SELECT l.entity_id, l.request_id FROM finance_audit_log l
       WHERE l.business_id=v_biz AND l.request_id IS NOT NULL
       GROUP BY 1,2 HAVING count(*)>1) x;
    v_c := v_c || finance_hc_mk('audit_duplicated_per_request','audit','Más de un evento por request',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Un evento de negocio por request' ELSE n||' request(s) con más de un evento de negocio' END);

    -- §5: la fecha economica del evento debe coincidir con la del asiento que creo.
    SELECT count(*) INTO n FROM finance_audit_log l
     WHERE l.business_id=v_biz AND l.economic_date IS NULL AND l.source_rpc IS NOT NULL;
    v_c := v_c || finance_hc_mk('audit_without_economic_date','audit','Eventos sin fecha económica',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Todo evento de una RPC lleva su fecha económica' ELSE n||' evento(s) sin economic_date' END);

    -- La compensacion de una anulacion debe fecharse el dia de la anulacion, no
    -- en el periodo original. (Una compensacion que REFERENCIA un asiento de un
    -- periodo cerrado es correcta y NO se marca: lo que importa es su propia fecha.)
    SELECT count(*) INTO n FROM finance_audit_log l JOIN comprobante_annulments a
        ON a.comprobante_id=l.entity_id AND a.status='completed'
     WHERE l.business_id=v_biz AND l.source_rpc='annul_comprobante_atomic'
       AND v_has_anndate AND a.annulment_date IS NOT NULL
       AND l.economic_date IS DISTINCT FROM a.annulment_date;
    v_c := v_c || finance_hc_mk('audit_date_vs_entry','audit','Fecha del evento vs fecha del asiento',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'La fecha de cada evento coincide con la del asiento que creó'
           ELSE n||' evento(s) con fecha distinta a la de su anulación' END);

    SELECT count(*) INTO n FROM finance_audit_log
     WHERE business_id=v_biz AND source_rpc='finance_audit_backstop';
    v_c := v_c || finance_hc_mk('backstop_events','audit','Escrituras E1 capturadas por el backstop',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Ninguna escritura directa a tablas E1 fuera de una RPC gestionada'
           ELSE n||' escritura(s) E1 sin evento explícito: alguien escribió fuera de las RPC canónicas' END);
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: idempotency  (tabla vacia => pass, no warn)
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*) INTO n FROM (
    SELECT business_id, idempotency_key FROM comprobante_annulments
     WHERE business_id=v_biz AND idempotency_key IS NOT NULL
     GROUP BY 1,2 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('request_keys_duplicated','idempotency','Claves de idempotencia duplicadas',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Sin claves duplicadas' ELSE n||' clave(s) repetidas: el índice único debería impedirlo' END);

  SELECT count(*) INTO n FROM comprobante_annulments
   WHERE business_id=v_biz AND (COALESCE(btrim(idempotency_key),'')='' OR COALESCE(btrim(request_hash),'')='');
  v_c := v_c || finance_hc_mk('request_key_or_hash_empty','idempotency','Requests sin clave o sin hash',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Toda request tiene clave y hash' ELSE n||' request(s) sin clave o sin hash' END);

  SELECT count(*) INTO n FROM comprobante_annulments
   WHERE business_id=v_biz AND status IS NOT NULL AND status NOT IN ('completed','processing');
  v_c := v_c || finance_hc_mk('request_unknown_status','idempotency','Estados de request desconocidos',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todos los estados son conocidos (status NULL = legacy M6 compatible)'
         ELSE n||' request(s) con estado no reconocido' END);

  -- MD5 (32 hex) = M6; SHA-256 (64 hex) = M7. Ambos coexisten: es info.
  SELECT count(*) INTO n FROM comprobante_annulments
   WHERE business_id=v_biz AND length(request_hash)=32;
  v_c := v_c || finance_hc_mk('request_hash_legacy_md5','idempotency','Requests con hash MD5 (pre-M7)',
    CASE WHEN n=0 THEN 'pass' ELSE 'info' END, 'info', n, 0,
    CASE WHEN n=0 THEN 'Todos los hashes son SHA-256 (algoritmo declarado por M7)'
         ELSE n||' request(s) con hash MD5 heredado de M6. Un reintento de esas claves daría IDEMPOTENCY_CONFLICT en vez de replay; el índice único por comprobante impide la doble anulación igual' END);

  IF v_has_repl THEN
    SELECT count(*) INTO n FROM comprobante_payment_replace_requests q
     WHERE q.business_id=v_biz AND q.status='completed' AND q.new_payment_id IS NULL;
    v_c := v_c || finance_hc_mk('request_completed_without_entity','idempotency','Requests completadas sin entidad',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Toda request completada tiene su entidad resultante' ELSE n||' completadas sin pago resultante' END);

    SELECT count(*) INTO n FROM comprobante_payment_replace_requests q
     WHERE q.business_id=v_biz AND q.status='stale_source' AND q.new_payment_id IS NOT NULL;
    v_c := v_c || finance_hc_mk('request_stale_with_entity','idempotency','Requests stale con entidad',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Ninguna request rechazada produjo entidad' ELSE n||' stale_source con new_payment_id: reemplazó pese a ser rechazada' END);

    SELECT count(*) INTO n FROM comprobante_payment_replace_requests q
     WHERE q.business_id=v_biz AND q.status='processing' AND q.created_at < now() - interval '1 hour';
    v_c := v_c || finance_hc_mk('request_processing_stale','idempotency','Reservas colgadas',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Sin reservas colgadas' ELSE n||' request(s) en processing hace más de una hora' END);

    SELECT count(*) INTO n FROM comprobante_payment_replace_requests q
      JOIN comprobantes c ON c.id=q.comprobante_id
     WHERE q.business_id=v_biz AND c.business_id <> q.business_id;
    v_c := v_c || finance_hc_mk('request_cross_business','idempotency','Requests cross-business',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Sin requests cruzadas de negocio' ELSE n||' request(s) apuntan a otro negocio' END);
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: payments (append-only)
  -- ══════════════════════════════════════════════════════════════════════════
  IF v_has_repl THEN
    SELECT count(*) INTO n FROM comprobante_payments
     WHERE business_id=v_biz AND num_nonnulls(replaced_at, replaced_by, replacement_payment_id) NOT IN (0,3);
    v_c := v_c || finance_hc_mk('replacement_metadata_partial','payments','Metadata de reemplazo parcial',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'La metadata de reemplazo está completa o ausente' ELSE n||' pago(s) con metadata parcial' END);

    SELECT count(*) INTO n FROM comprobante_payments
     WHERE business_id=v_biz AND replacement_payment_id = id;
    v_c := v_c || finance_hc_mk('replacement_self_reference','payments','Pago que se sustituye a sí mismo',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Sin auto-referencias' ELSE n||' pago(s) apuntan a sí mismos' END);

    SELECT count(*) INTO n FROM comprobante_payments p LEFT JOIN comprobante_payments s ON s.id=p.replacement_payment_id
     WHERE p.business_id=v_biz AND p.replacement_payment_id IS NOT NULL
       AND (s.id IS NULL OR s.comprobante_id <> p.comprobante_id OR s.business_id <> p.business_id);
    v_c := v_c || finance_hc_mk('replacement_chain_broken','payments','Cadena de reemplazo rota',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Toda cadena de reemplazo resuelve dentro del mismo comprobante y negocio'
           ELSE n||' sustituto(s) inexistentes o de otro comprobante/negocio' END);

    -- Header vs suma de pagos VIVOS. Un cobro mixto con varias filas vivas es
    -- VALIDO: no se marca por tener mas de una linea, solo si el total no cuadra.
    SELECT count(*), COALESCE(SUM(abs(dif)),0) INTO n, m FROM (
      SELECT c.id, COALESCE(c.total_cobrado,0) - COALESCE(SUM(p.amount_ars) FILTER (WHERE p.replaced_at IS NULL),0) AS dif
        FROM comprobantes c LEFT JOIN comprobante_payments p ON p.comprobante_id=c.id
       WHERE c.business_id=v_biz GROUP BY c.id, c.total_cobrado
      HAVING COALESCE(c.total_cobrado,0) <> COALESCE(SUM(p.amount_ars) FILTER (WHERE p.replaced_at IS NULL),0)) x;
    v_c := v_c || finance_hc_mk('header_vs_live_payments','payments','Header vs suma de cobros vigentes',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, m,
      CASE WHEN n=0 THEN 'total_cobrado coincide con la suma de los pagos vigentes'
           ELSE n||' comprobante(s) con header distinto de sus pagos vivos (los cobros mixtos con varias filas vivas son válidos y no se cuentan acá)' END);

    SELECT count(*) INTO n FROM comprobante_payment_replace_requests q
     WHERE q.business_id=v_biz AND q.status='completed'
       AND NOT EXISTS (SELECT 1 FROM financial_movements f
                        WHERE f.comprobante_id=q.comprobante_id AND f.reference_type='comprobante_payment_replace');
    v_c := v_c || finance_hc_mk('replacement_without_compensation','payments','Reemplazos sin compensación',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Todo reemplazo completado tiene su compensación de caja'
           ELSE n||' reemplazo(s) sin FM compensatorio: el cobro viejo sigue contado' END);

    SELECT count(*) INTO n FROM financial_movements f
     WHERE f.business_id=v_biz AND f.reference_type='comprobante_payment_replace'
       AND NOT EXISTS (SELECT 1 FROM comprobante_payments p WHERE p.id=f.reference_id AND p.replaced_at IS NOT NULL);
    v_c := v_c || finance_hc_mk('compensation_without_replacement','payments','Compensación sin reemplazo',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Toda compensación de reemplazo corresponde a un pago reemplazado'
           ELSE n||' compensación(es) sin pago reemplazado detrás' END);
  END IF;

  -- Pagos creados DESPUES de la anulacion del comprobante.
  IF v_has_anndate THEN
    SELECT count(*), COALESCE(SUM(p.amount_ars),0) INTO n, m
      FROM comprobante_payments p JOIN comprobante_annulments a
        ON a.comprobante_id=p.comprobante_id AND a.status='completed'
     WHERE p.business_id=v_biz AND p.created_at > a.created_at;
    v_c := v_c || finance_hc_mk('payment_after_annulment','payments','Cobros posteriores a la anulación',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
      CASE WHEN n=0 THEN 'Ningún cobro se registró después de anular su comprobante'
           ELSE n||' cobro(s) creados después de la anulación' END);
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: annulments
  -- ══════════════════════════════════════════════════════════════════════════
  -- Un anulado con NOTA DE CREDITO no necesita registro interno: es la via
  -- fiscal. Solo se marca el que no tiene ni registro ni NC.
  SELECT count(*), COALESCE(SUM(c.total),0),
         COALESCE(jsonb_agg(jsonb_build_object('comprobante_id',c.id,'numero',COALESCE(c.numero_fiscal,c.numero,c.number),
                  'fecha',(COALESCE(c.fecha,c.date,c.created_at) AT TIME ZONE 'America/Argentina/Cordoba')::date,
                  'total',c.total)),'[]'::jsonb)
    INTO n, m, d
    FROM comprobantes c
   WHERE c.business_id=v_biz
     AND (c.estado='anulado' OR c.status='cancelled' OR c.estado_comercial='anulado')
     AND NOT EXISTS (SELECT 1 FROM comprobante_annulments a WHERE a.comprobante_id=c.id AND a.status='completed')
     AND NOT EXISTS (SELECT 1 FROM comprobantes nc WHERE nc.comprobante_original_id=c.id
                       AND COALESCE(nc.tipo,nc.type)='nota_credito' AND nc.estado <> 'anulado');
  v_c := v_c || finance_hc_mk('annulled_without_record','annulments','Anulados sin registro canónico',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
    CASE WHEN n=0 THEN 'Toda anulación tiene registro canónico o nota de crédito'
         ELSE n||' comprobante(s) anulados sin registro ni NC: el ledger no puede derivar su compensación y su venta reaparece en el período original' END,
    '{}'::jsonb, d);

  SELECT count(*) INTO n FROM comprobante_annulments a
   WHERE a.business_id=v_biz AND NOT EXISTS (SELECT 1 FROM comprobantes c WHERE c.id=a.comprobante_id);
  v_c := v_c || finance_hc_mk('annulment_record_orphan','annulments','Registros de anulación huérfanos',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todo registro resuelve a un comprobante' ELSE n||' registro(s) sin comprobante' END);

  SELECT count(*) INTO n FROM (
    SELECT comprobante_id FROM comprobante_annulments
     WHERE business_id=v_biz AND status='completed' GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('annulment_multiple_records','annulments','Anulaciones múltiples por comprobante',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Una sola anulación por comprobante' ELSE n||' comprobante(s) con más de una anulación: doble compensación' END);

  SELECT count(*) INTO n FROM comprobantes c
   WHERE c.business_id=v_biz
     AND (COALESCE(c.estado,'')='anulado' OR COALESCE(c.estado_comercial,'')='anulado' OR COALESCE(c.status,'')='cancelled')
     AND NOT (COALESCE(c.estado,'')='anulado' AND COALESCE(c.estado_comercial,'')='anulado' AND COALESCE(c.status,'')='cancelled');
  v_c := v_c || finance_hc_mk('annulment_signals_partial','annulments','Señales de anulación contradictorias',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'estado, estado_comercial y status coinciden'
         ELSE n||' comprobante(s) con una señal diciendo anulado y otra no' END);

  SELECT count(*) INTO n FROM comprobante_annulments a JOIN comprobantes c ON c.id=a.comprobante_id
   WHERE a.business_id=v_biz AND a.status='completed'
     AND COALESCE(c.estado,'') <> 'anulado' AND COALESCE(c.estado_comercial,'') <> 'anulado'
     AND COALESCE(c.status,'') <> 'cancelled';
  v_c := v_c || finance_hc_mk('annulment_resurrected','annulments','Comprobantes resucitados',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Ningún anulado volvió a estar activo'
         ELSE n||' comprobante(s) con registro de anulación pero operativamente activos' END);

  SELECT count(*) INTO n FROM comprobante_annulments a JOIN comprobantes c ON c.id=a.comprobante_id
   WHERE a.business_id=v_biz
     AND COALESCE(CASE WHEN v_has_anndate THEN a.annulment_date ELSE NULL END,
                  (a.created_at AT TIME ZONE 'America/Argentina/Cordoba')::date)
       < (COALESCE(c.fecha,c.date,c.created_at) AT TIME ZONE 'America/Argentina/Cordoba')::date;
  v_c := v_c || finance_hc_mk('annulment_date_impossible','annulments','Anulación anterior a la venta',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Ninguna anulación precede a su venta' ELSE n||' anulación(es) fechadas antes de la venta' END);

  SELECT count(*) INTO n FROM comprobante_annulments a JOIN comprobantes c ON c.id=a.comprobante_id
   WHERE a.business_id=v_biz AND c.business_id <> a.business_id;
  v_c := v_c || finance_hc_mk('annulment_cross_business','annulments','Anulaciones cross-business',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Sin anulaciones cruzadas de negocio' ELSE n||' anulación(es) de otro negocio' END);

  -- Restauracion de stock duplicada: se AGRUPA por inventory_id, porque las
  -- lineas repetidas del mismo producto son validas.
  SELECT count(*) INTO n FROM (
    SELECT m2.reference_id, m2.inventory_item_id FROM inventory_movements m2
     WHERE m2.business_id=v_biz AND m2.reference_type='comprobante' AND m2.movement_type='return'
     GROUP BY 1,2 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('annulment_stock_restored_twice','annulments','Stock restaurado dos veces',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Ningún inventario se restauró más de una vez por comprobante'
         ELSE n||' inventario(s) restaurados dos veces: stock inflado' END);

  SELECT count(*) INTO n FROM (
    SELECT f.reference_id FROM financial_movements f
     WHERE f.business_id=v_biz AND f.reference_type='annulment_reversal' AND f.reference_id IS NOT NULL
     GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('annulment_cashflow_double_reversal','annulments','Caja revertida dos veces',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Una devolución por cada cobro' ELSE n||' cobro(s) devueltos más de una vez' END);

  SELECT count(*) INTO n FROM (
    SELECT b.reference_comprobante_id FROM business_finance_entries b
     WHERE b.business_id=v_biz AND b.source='annulment' AND b.category='mercaderia' AND b.amount_ars < 0
     GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('annulment_cogs_double_reversal','annulments','COGS revertido dos veces',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'El COGS se revierte una sola vez por anulación' ELSE n||' comprobante(s) con COGS revertido dos veces' END);

  SELECT count(*) INTO n FROM comprobante_annulments a
   WHERE a.business_id=v_biz AND a.status='completed'
     AND EXISTS (SELECT 1 FROM comprobantes nc WHERE nc.comprobante_original_id=a.comprobante_id
                   AND COALESCE(nc.tipo,nc.type)='nota_credito' AND nc.estado <> 'anulado');
  v_c := v_c || finance_hc_mk('annulment_and_credit_note','annulments','Anulación interna + nota de crédito',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Las dos vías son mutuamente excluyentes (la NC exige CAE y la anulación lo rechaza)'
         ELSE n||' comprobante(s) revertidos por AMBAS vías: doble reversión' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: credit_notes — credit_reversal e inventory_return SEPARADOS
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*), COALESCE(SUM(nc.total),0) INTO n, m FROM comprobantes nc
   WHERE nc.business_id=v_biz AND COALESCE(nc.tipo,nc.type)='nota_credito' AND nc.estado='emitido'
     AND NOT EXISTS (SELECT 1 FROM financial_movements f
                      WHERE f.comprobante_id=nc.id AND f.type='expense');
  v_c := v_c || finance_hc_mk('credit_note_cash_not_compensated','credit_notes','NC sin compensación de caja',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, m,
    CASE WHEN n=0 THEN 'Toda NC emitida compensó su cobro (dimensión credit_reversal)'
         ELSE n||' NC sin movimiento compensatorio: el ingreso sigue contado' END);

  SELECT count(*) INTO n FROM comprobantes nc
   WHERE nc.business_id=v_biz AND COALESCE(nc.tipo,nc.type)='nota_credito'
     AND (nc.comprobante_original_id IS NULL
          OR NOT EXISTS (SELECT 1 FROM comprobantes o WHERE o.id=nc.comprobante_original_id));
  v_c := v_c || finance_hc_mk('credit_note_without_original','credit_notes','NC sin comprobante original',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Toda NC referencia su original' ELSE n||' NC sin original válido' END);

  SELECT count(*) INTO n FROM (
    SELECT nc.comprobante_original_id FROM comprobantes nc
     WHERE nc.business_id=v_biz AND COALESCE(nc.tipo,nc.type)='nota_credito' AND nc.estado <> 'anulado'
       AND nc.comprobante_original_id IS NOT NULL GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('credit_note_duplicated','credit_notes','NC duplicadas por comprobante',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Una NC activa por comprobante' ELSE n||' comprobante(s) con más de una NC activa: doble reversión' END);

  -- NC que dice restaurar stock (copia inventory_id) pero no dejo movimiento.
  SELECT count(*) INTO n FROM comprobantes nc
   WHERE nc.business_id=v_biz AND COALESCE(nc.tipo,nc.type)='nota_credito'
     AND EXISTS (SELECT 1 FROM comprobante_items i WHERE i.comprobante_id=nc.id AND i.inventory_id IS NOT NULL)
     AND NOT EXISTS (SELECT 1 FROM inventory_movements m2 WHERE m2.reference_id=nc.id AND m2.movement_type='return');
  v_c := v_c || finance_hc_mk('credit_note_claims_stock_without_movement','credit_notes','NC con inventario pero sin devolución',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Ninguna NC declara inventario sin registrar la devolución'
         ELSE n||' NC con inventory_id en sus ítems pero sin inventory_movement de entrada' END);

  -- SEMANTICA APROBADA: una NC financiera pura (sin retorno fisico) es INFO.
  SELECT count(*), COALESCE(SUM(i.costo_total),0) INTO n, m
    FROM comprobantes nc JOIN comprobantes o ON o.id=nc.comprobante_original_id
    JOIN comprobante_items i ON i.comprobante_id=o.id
   WHERE nc.business_id=v_biz AND COALESCE(nc.tipo,nc.type)='nota_credito' AND nc.estado='emitido'
     AND i.costo_total > 0
     AND NOT EXISTS (SELECT 1 FROM inventory_movements m2 WHERE m2.reference_id=o.id AND m2.movement_type='return');
  v_c := v_c || finance_hc_mk('credit_note_without_physical_return','credit_notes','NC sin retorno físico (COGS retenido)',
    CASE WHEN n=0 THEN 'pass' ELSE 'info' END, 'info', n, m,
    CASE WHEN n=0 THEN 'Sin NC con COGS retenido'
         ELSE n||' NC revirtieron ingreso/cobro sin devolución física: el COGS ('||round(m,2)||') permanece y produce pérdida. COMPORTAMIENTO ECONÓMICO VÁLIDO: la NC revierte dinero, no mercadería. El COGS solo se revierte si hubo devolución física. No es un fallo' END,
    jsonb_build_object('semantica','credit_reversal e inventory_return son dimensiones separadas',
                       'politica','NC total sin retorno => ventas netas 0, COGS positivo, pérdida legítima'));

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: accounting_classification (BFE)
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*) INTO n FROM business_finance_entries WHERE business_id=v_biz AND economic_class IS NULL;
  v_c := v_c || finance_hc_mk('bfe_null_class','accounting_classification','Asientos sin clase económica',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todo asiento tiene clase económica' ELSE n||' asiento(s) sin clasificar' END);

  -- Mirrors historicos de anulacion: deuda de clasificacion EXPLICADA.
  -- Requisitos para degradar a info: vinculados 1-a-1 con una anulacion y fuera
  -- del operating result (revenue_collection_mirror/cogs_mirror lo estan; el
  -- legacy_unclassified solo alimenta data_quality_flags).
  SELECT count(*), COALESCE(SUM(b.amount_ars),0) INTO n, m
    FROM business_finance_entries b
   WHERE b.business_id=v_biz AND b.economic_class='legacy_unclassified' AND b.source='annulment'
     AND EXISTS (SELECT 1 FROM comprobantes c WHERE c.id=b.reference_comprobante_id
                   AND (c.estado='anulado' OR c.status='cancelled' OR c.estado_comercial='anulado'));
  v_c := v_c || finance_hc_mk('bfe_legacy_annulment_mirrors','accounting_classification','Mirrors históricos de anulación',
    CASE WHEN n=0 THEN 'pass' ELSE 'info' END, 'info', n, m,
    CASE WHEN n=0 THEN 'Sin deuda de clasificación por mirrors de anulación'
         ELSE n||' mirror(s) de anulación con clase legacy_unclassified, vinculados uno a uno con su anulación. NO alimentan operating_result (solo data_quality_flags). Deuda de clasificación explicada, no un error' END,
    jsonb_build_object('tipo','legacy_classification_debt','remediacion','ninguna: reclasificar seria un backfill sobre asientos historicos'));

  -- El resto de legacy_unclassified SI conserva alerta.
  SELECT count(*), COALESCE(SUM(b.amount_ars),0) INTO n, m
    FROM business_finance_entries b
   WHERE b.business_id=v_biz AND b.economic_class='legacy_unclassified'
     AND NOT (b.source='annulment' AND EXISTS (SELECT 1 FROM comprobantes c WHERE c.id=b.reference_comprobante_id
                AND (c.estado='anulado' OR c.status='cancelled' OR c.estado_comercial='anulado')));
  v_c := v_c || finance_hc_mk('bfe_legacy_unclassified_other','accounting_classification','Asientos sin clasificar (otro origen)',
    CASE WHEN n=0 THEN 'pass' WHEN abs(m) > 100000 THEN 'fail' ELSE 'warn' END,
    CASE WHEN n=0 THEN 'info' WHEN abs(m) > 100000 THEN 'high' ELSE 'medium' END, n, m,
    CASE WHEN n=0 THEN 'Sin asientos legacy_unclassified de origen desconocido'
         ELSE n||' asiento(s) sin clasificar por '||round(m,2)||' ARS, de origen distinto a un mirror de anulación conocido' END);

  SELECT count(*) INTO n FROM (
    SELECT reference_comprobante_id FROM business_finance_entries
     WHERE business_id=v_biz AND category='mercaderia' AND amount_ars > 0 AND reference_comprobante_id IS NOT NULL
     GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('bfe_cogs_duplicated','accounting_classification','COGS duplicado',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Un asiento de COGS por comprobante' ELSE n||' comprobante(s) con COGS duplicado' END);

  -- M7 7E.3 — PREDICADO CORREGIDO.
  --
  -- El anterior contaba filas: count de BFE income > 1 por comprobante. Eso
  -- marcaba como error critico TODO cobro MIXTO, que genera legitimamente un
  -- espejo `revenue_collection_mirror` por cada medio de pago. Medido en
  -- produccion: 2 casos marcados, los DOS correctos
  --   1.000   = 500 efectivo + 500 transferencia
  --   110.000 = 100.000 efectivo + 10.000 transferencia
  -- En ambos: pagos = espejos = total. Cero impacto en P&L. Era un falso
  -- positivo, y encima critical, sobre una funcionalidad que el POS soporta:
  -- iba a dispararse en cada venta mixta.
  --
  -- El invariante economico real es que el espejo de ingreso NO PUEDE SUPERAR
  -- lo efectivamente cobrado.
  --
  -- Se compara contra los PAGOS y no contra total_bruto: el recargo al cliente
  -- hace que lo cobrado supere legitimamente al bruto. Medido: 8 comprobantes
  -- donde bfe = total_cobrado = pagos y el "exceso" sobre el bruto es
  -- exactamente el recargo de tarjeta. Usar total_bruto habria cambiado un
  -- falso positivo de 2 por otro de 8.
  --
  -- Se comparan ACTIVOS contra ACTIVOS: se excluyen los espejos revertidos
  -- (reversed_at) y los pagos reemplazados (replaced_at).
  --
  -- Solo evalua cuando HAY cobro que espejar. Un espejo sin ningun pago es otro
  -- invariante (no es duplicacion) y no le corresponde a este check.
  SELECT count(*), COALESCE(SUM(exceso),0) INTO n, m FROM (
    SELECT b.reference_comprobante_id,
           SUM(b.amount_ars) - COALESCE(p.pagos,0) AS exceso
      FROM business_finance_entries b
      JOIN (SELECT comprobante_id, SUM(amount_ars) AS pagos, count(*) AS n_pagos
              FROM comprobante_payments
             WHERE replaced_at IS NULL
             GROUP BY 1) p ON p.comprobante_id = b.reference_comprobante_id
     WHERE b.business_id=v_biz AND b.type='income' AND b.amount_ars > 0
       AND b.reference_comprobante_id IS NOT NULL
       AND b.reversed_at IS NULL
       AND p.n_pagos > 0
     GROUP BY b.reference_comprobante_id, p.pagos
    HAVING SUM(b.amount_ars) > COALESCE(p.pagos,0) + 1.00) x;
  v_c := v_c || finance_hc_mk('bfe_income_duplicated','accounting_classification','Ingreso duplicado',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
    CASE WHEN n=0 THEN 'Ningun comprobante contabiliza mas ingreso del que cobro (los cobros mixtos son validos)'
         ELSE n||' comprobante(s) con ingreso espejado por encima de lo cobrado' END);

  SELECT count(*) INTO n FROM (
    SELECT reference_comprobante_id FROM business_finance_entries
     WHERE business_id=v_biz AND category='comisiones_cobro' AND amount_ars > 0 AND reference_comprobante_id IS NOT NULL
     GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('bfe_commission_duplicated','accounting_classification','Comisión duplicada',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Una comisión por comprobante' ELSE n||' comprobante(s) con comisión duplicada' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: cashflow
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*) INTO n FROM (
    SELECT business_id FROM cajas WHERE business_id=v_biz AND status='abierta' GROUP BY 1 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('multiple_open_cajas','cashflow','Más de una caja abierta',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'A lo sumo una caja abierta' ELSE 'Hay más de una caja abierta: los cobros pueden caer en la equivocada' END);

  SELECT count(*), COALESCE(SUM(amount_ars),0) INTO n, m FROM financial_movements
   WHERE business_id=v_biz AND metodo_pago='efectivo' AND caja_id IS NULL;
  v_c := v_c || finance_hc_mk('cash_without_caja','cashflow','Efectivo sin caja',
    CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, m,
    CASE WHEN n=0 THEN 'Todo movimiento en efectivo tiene caja'
         ELSE n||' movimiento(s) en efectivo sin caja por '||round(m,2)||' ARS. Clasificación M6 heredada: el neto y las referencias son correctos, solo falta la sesión' END);

  SELECT count(*) INTO n FROM financial_movements f JOIN cajas j ON j.id=f.caja_id
   WHERE f.business_id=v_biz AND j.business_id <> f.business_id;
  v_c := v_c || finance_hc_mk('caja_cross_business','cashflow','Movimientos en caja de otro negocio',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Sin movimientos en cajas ajenas' ELSE n||' movimiento(s) en la caja de otro negocio' END);

  SELECT count(*) INTO n FROM financial_movements f JOIN cajas j ON j.id=f.caja_id
   WHERE f.business_id=v_biz AND j.closed_at IS NOT NULL AND f.created_at > j.closed_at;
  v_c := v_c || finance_hc_mk('fm_after_caja_close','cashflow','Movimientos posteriores al cierre de caja',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Ninguna caja cerrada recibió movimientos después'
         ELSE n||' movimiento(s) agregados a una caja ya cerrada' END);

  SELECT count(*) INTO n FROM financial_movements f
   WHERE f.business_id=v_biz AND f.reference_type IN ('annulment_reversal','comprobante_payment_replace')
     AND f.reference_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM financial_movements o WHERE o.id=f.reference_id);
  v_c := v_c || finance_hc_mk('reversal_without_original','cashflow','Reversas sin movimiento original',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Toda reversa referencia un original existente' ELSE n||' reversa(s) sin original' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: pnl_ledger
  -- ══════════════════════════════════════════════════════════════════════════
  IF v_has_ledger THEN
    SELECT count(*) INTO n FROM comprobante_annulments a
     WHERE a.business_id=v_biz AND a.status='completed'
       AND NOT EXISTS (SELECT 1 FROM v_finance_sales_ledger l
                        WHERE l.comprobante_id=a.comprobante_id AND l.event_type='annulment');
    v_c := v_c || finance_hc_mk('annulment_without_ledger_event','pnl_ledger','Anulaciones sin evento en el ledger',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
      CASE WHEN n=0 THEN 'Toda anulación canónica produce su evento compensatorio'
           ELSE n||' anulación(es) sin evento en el ledger: su venta no se compensa' END);

    -- El neto de un comprobante ANULADO con registro debe ser 0 en el ledger.
    SELECT count(*), COALESCE(SUM(abs(neto)),0) INTO n, m FROM (
      SELECT l.comprobante_id, SUM(l.sales_amount_ars) AS neto
        FROM v_finance_sales_ledger l
       WHERE l.business_id=v_biz AND l.is_credit_note=false
         AND EXISTS (SELECT 1 FROM comprobante_annulments a
                      WHERE a.comprobante_id=l.comprobante_id AND a.status='completed')
       GROUP BY 1 HAVING SUM(l.sales_amount_ars) <> 0) x;
    v_c := v_c || finance_hc_mk('annulled_ledger_not_netting','pnl_ledger','Anulados que no netean a cero',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
      CASE WHEN n=0 THEN 'Todo comprobante anulado con registro netea a cero en el ledger'
           ELSE n||' anulado(s) no netean: quedan '||round(m,2)||' ARS sin compensar' END);

    -- v_finance_pnl debe coincidir EXACTAMENTE con la agregacion del ledger.
    SELECT count(*), COALESCE(SUM(abs(dif)),0) INTO n, m FROM (
      SELECT p.period_date, p.gross_sales - COALESCE(l.s,0) AS dif
        FROM v_finance_pnl p
        LEFT JOIN (SELECT period_date, SUM(gross_amount_ars) AS s FROM v_finance_sales_ledger
                    WHERE business_id=v_biz AND is_credit_note=false GROUP BY 1) l
          ON l.period_date=p.period_date
       WHERE p.business_id=v_biz AND round(p.gross_sales,2) <> round(COALESCE(l.s,0),2)) x;
    v_c := v_c || finance_hc_mk('pnl_vs_ledger_mismatch','pnl_ledger','P&L vs agregación del ledger',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
      CASE WHEN n=0 THEN 'v_finance_pnl coincide con la agregación del ledger en todos los períodos'
           ELSE n||' período(s) donde el P&L no coincide con el ledger, por '||round(m,2)||' ARS' END);

    -- Servicios: no deben inventar COGS.
    SELECT count(*) INTO n FROM v_finance_sales_ledger l
     WHERE l.business_id=v_biz AND l.tipo_linea='servicio' AND COALESCE(l.cogs_amount_ars,0) <> 0;
    v_c := v_c || finance_hc_mk('service_with_cogs','pnl_ledger','Servicios con COGS',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Los servicios no inventan COGS' ELSE n||' línea(s) de servicio con costo de mercadería' END);
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: accounts_receivable
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*), COALESCE(SUM(abs(dif)),0) INTO n, m FROM (
    SELECT a.id, COALESCE(a.balance,0) - COALESCE((SELECT SUM(mm.debit-mm.credit) FROM account_movements mm
                                                    WHERE mm.account_id=a.id),0) AS dif
      FROM accounts a WHERE a.business_id=v_biz
     ) x WHERE dif <> 0;
  v_c := v_c || finance_hc_mk('account_balance_mismatch','accounts_receivable','Saldo distinto de sus movimientos',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
    CASE WHEN n=0 THEN 'Todo saldo persistido coincide con la suma canónica de movimientos'
         ELSE n||' cuenta(s) con saldo desalineado por '||round(m,2)||' ARS' END);

  SELECT count(*) INTO n FROM account_movements mm JOIN accounts a ON a.id=mm.account_id
   WHERE mm.business_id=v_biz AND a.business_id <> mm.business_id;
  v_c := v_c || finance_hc_mk('account_cross_business','accounts_receivable','Cuentas corrientes cross-business',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Sin cuentas cruzadas de negocio' ELSE n||' movimiento(s) sobre una cuenta de otro negocio' END);

  SELECT count(*) INTO n FROM account_movements mm
   WHERE mm.business_id=v_biz AND NOT EXISTS (SELECT 1 FROM accounts a WHERE a.id=mm.account_id);
  v_c := v_c || finance_hc_mk('account_movement_orphan','accounts_receivable','Movimientos de CC huérfanos',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todo movimiento resuelve a una cuenta' ELSE n||' movimiento(s) sin cuenta' END);

  SELECT count(*) INTO n FROM (
    SELECT reference_id, type FROM account_movements
     WHERE business_id=v_biz AND reference_type='comprobante' AND reference_id IS NOT NULL
     GROUP BY 1,2 HAVING count(*)>1) x;
  v_c := v_c || finance_hc_mk('account_movement_duplicated','accounts_receivable','Movimientos de CC duplicados',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Sin movimientos duplicados por comprobante' ELSE n||' referencia(s) con movimiento duplicado' END);

  SELECT count(*), COALESCE(SUM(x.deuda),0) INTO n, m FROM (
    SELECT c.id, SUM(mm.debit-mm.credit) AS deuda FROM comprobantes c
      JOIN account_movements mm ON mm.reference_id=c.id AND mm.reference_type='comprobante'
     WHERE c.business_id=v_biz AND (c.estado='anulado' OR c.status='cancelled')
     GROUP BY c.id HAVING SUM(mm.debit-mm.credit) > 0.01) x;
  v_c := v_c || finance_hc_mk('annulled_cc_without_compensation','accounts_receivable','Anulados con deuda de CC vigente',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, m,
    CASE WHEN n=0 THEN 'Ningún anulado dejó deuda de cuenta corriente viva'
         ELSE n||' comprobante(s) anulados con '||round(m,2)||' ARS de deuda sin compensar' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: inventory
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*) INTO n FROM comprobante_items
   WHERE business_id=v_biz AND cantidad IS NOT NULL AND cantidad <> floor(cantidad);
  v_c := v_c || finance_hc_mk('item_decimal_quantity','inventory','Cantidades decimales',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todas las cantidades son enteras (TechRepair Pro maneja solo unidades enteras)'
         ELSE n||' ítem(s) con cantidad decimal' END);

  SELECT count(*) INTO n FROM comprobante_items WHERE business_id=v_biz AND COALESCE(cantidad,0) <= 0;
  v_c := v_c || finance_hc_mk('item_non_positive_quantity','inventory','Cantidades no positivas',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todas las cantidades son positivas' ELSE n||' ítem(s) con cantidad <= 0' END);

  SELECT count(*) INTO n FROM comprobante_items ci
   WHERE ci.business_id=v_biz AND ci.inventory_id IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM inventory i WHERE i.id=ci.inventory_id);
  v_c := v_c || finance_hc_mk('item_inventory_missing','inventory','Ítems con inventario inexistente',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
    CASE WHEN n=0 THEN 'Todo ítem resuelve a su inventario' ELSE n||' ítem(s) apuntan a un inventario inexistente' END);

  SELECT count(*) INTO n FROM inventory_movements m2 JOIN inventory i ON i.id=m2.inventory_item_id
   WHERE m2.business_id=v_biz AND i.business_id <> m2.business_id;
  v_c := v_c || finance_hc_mk('inventory_cross_business','inventory','Inventario cross-business',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Sin movimientos sobre inventario de otro negocio' ELSE n||' movimiento(s) cruzados' END);

  SELECT count(*) INTO n FROM inventory_movements
   WHERE business_id=v_biz AND reference_id IS NULL;
  v_c := v_c || finance_hc_mk('inventory_movement_orphan','inventory','Movimientos de stock sin entidad',
    CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
    CASE WHEN n=0 THEN 'Todo movimiento referencia su entidad'
         ELSE n||' movimiento(s) sin referencia: ajustes manuales legacy, sin impacto económico' END);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: multi_tenant  (cualquier fila => fail/critical)
  -- ══════════════════════════════════════════════════════════════════════════
  SELECT count(*), jsonb_build_object(
      'comprobante_cliente', (SELECT count(*) FROM comprobantes c JOIN customers k ON k.id=c.customer_id
                               WHERE c.business_id=v_biz AND k.business_id<>c.business_id),
      'comprobante_orden',   (SELECT count(*) FROM comprobantes c JOIN orders o ON o.id=c.order_id
                               WHERE c.business_id=v_biz AND o.business_id<>c.business_id),
      'pago_comprobante',    (SELECT count(*) FROM comprobante_payments p JOIN comprobantes c ON c.id=p.comprobante_id
                               WHERE p.business_id=v_biz AND c.business_id<>p.business_id),
      'fm_comprobante',      (SELECT count(*) FROM financial_movements f JOIN comprobantes c ON c.id=f.comprobante_id
                               WHERE f.business_id=v_biz AND c.business_id<>f.business_id),
      'bfe_comprobante',     (SELECT count(*) FROM business_finance_entries b JOIN comprobantes c ON c.id=b.reference_comprobante_id
                               WHERE b.business_id=v_biz AND c.business_id<>b.business_id),
      'item_comprobante',    (SELECT count(*) FROM comprobante_items ci JOIN comprobantes c ON c.id=ci.comprobante_id
                               WHERE ci.business_id=v_biz AND c.business_id<>ci.business_id)
    ) INTO n, d
    FROM (SELECT 1) z;
  SELECT (SELECT count(*) FROM comprobantes c JOIN customers k ON k.id=c.customer_id WHERE c.business_id=v_biz AND k.business_id<>c.business_id)
       + (SELECT count(*) FROM comprobantes c JOIN orders o ON o.id=c.order_id WHERE c.business_id=v_biz AND o.business_id<>c.business_id)
       + (SELECT count(*) FROM comprobante_payments p JOIN comprobantes c ON c.id=p.comprobante_id WHERE p.business_id=v_biz AND c.business_id<>p.business_id)
       + (SELECT count(*) FROM financial_movements f JOIN comprobantes c ON c.id=f.comprobante_id WHERE f.business_id=v_biz AND c.business_id<>f.business_id)
       + (SELECT count(*) FROM business_finance_entries b JOIN comprobantes c ON c.id=b.reference_comprobante_id WHERE b.business_id=v_biz AND c.business_id<>b.business_id)
       + (SELECT count(*) FROM comprobante_items ci JOIN comprobantes c ON c.id=ci.comprobante_id WHERE ci.business_id=v_biz AND c.business_id<>ci.business_id)
    INTO n;
  v_c := v_c || finance_hc_mk('cross_business_references','multi_tenant','Referencias cross-business',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Aislamiento multi-tenant íntegro en todos los cruces financieros'
         ELSE n||' referencia(s) apuntan a entidades de otro negocio' END, d);

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: security
  -- GLOBALES: miran catalogo/grants, no filas del negocio. Un hallazgo de
  -- plataforma NO debe pintar de rojo el health check de cada comercio, asi que
  -- solo se incluyen con p_include_global=true (auditoria operativa, no el
  -- endpoint interactivo). §17.
  --
  -- 7C.1 §8: ademas revelan nombres de funciones, grants y configuracion de
  -- seguridad de la PLATAFORMA. p_include_global es un parametro del CLIENTE:
  -- por si solo no autoriza nada. Se exige una condicion REAL de operador —
  -- ser owner del negocio, verificado server-side. Si no lo es, los checks se
  -- reportan como OMITIDOS sin detalles sensibles, en vez de fallar: el
  -- contrato del frontend no se rompe.
  -- ══════════════════════════════════════════════════════════════════════════
  IF p_include_global AND NOT public.finance_hc_can_see_global(v_biz) THEN
    v_c := v_c || finance_hc_mk('global_checks_restricted','security','Diagnóstico de plataforma restringido',
      'info', 'info', 0, 0,
      'Los checks globales (configuración de seguridad y vías de escritura de la plataforma) '
      'requieren ser owner del negocio. Se omitieron sin exponer detalles.',
      jsonb_build_object('omitidos', jsonb_build_array('secdef_without_search_path','alternative_write_paths'),
                         'motivo','requiere_operador'));
  END IF;

  IF p_include_global AND public.finance_hc_can_see_global(v_biz) THEN
  SELECT count(*) INTO n FROM pg_proc p JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.prosecdef AND p.prokind='f'
     AND (p.proconfig IS NULL OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) cfg WHERE cfg LIKE 'search_path=%'));
  v_c := v_c || finance_hc_mk('secdef_without_search_path','security','SECURITY DEFINER sin search_path',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Toda función SECURITY DEFINER fija su search_path'
         ELSE n||' función(es) SECURITY DEFINER sin search_path fijo: vulnerables a secuestro de esquema' END);

  -- 7C.1a §9 — SECURITY DEFINER con schema NO CONFIABLE en el search_path.
  -- Un schema es no confiable si algun rol no confiable puede CREATE en el.
  -- Tambien falla por "$user" y por pg_temp en posicion insegura (omitido =
  -- se busca PRIMERO, doc PG 5.9.3).
  SELECT count(*) INTO n FROM pg_proc p
    JOIN pg_namespace ns ON ns.oid=p.pronamespace
   WHERE ns.nspname='public' AND p.prosecdef AND p.prokind IN ('f','p')
     AND p.proconfig IS NOT NULL
     AND EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%')
     AND (
       -- schema escribible por anon/authenticated/PUBLIC dentro del path
       EXISTS (SELECT 1 FROM unnest(string_to_array(
                 replace((SELECT c FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%'),'search_path=',''), ', ')) AS s
                WHERE btrim(s, '"') NOT IN ('pg_catalog','pg_temp','extensions')
                  AND (has_schema_privilege('anon', btrim(s,'"'), 'CREATE')
                    OR has_schema_privilege('authenticated', btrim(s,'"'), 'CREATE')
                    OR has_schema_privilege('public', btrim(s,'"'), 'CREATE')))
       -- "$user"
       OR EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%$user%')
       -- pg_temp omitido => se busca primero
       OR NOT EXISTS (SELECT 1 FROM unnest(p.proconfig) c WHERE c LIKE 'search_path=%pg_temp%')
     );
  v_c := v_c || finance_hc_mk('secdef_untrusted_search_path','security','SECURITY DEFINER con schema no confiable en el path',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Ninguna funcion privilegiada depende de un schema escribible por roles no confiables'
         ELSE n||' funcion(es) SECURITY DEFINER tienen en su search_path un schema escribible por anon/authenticated/PUBLIC, o "$user", o omiten pg_temp (que entonces se busca PRIMERO). Vector de shadowing.' END,
    jsonb_build_object('regla','un schema es confiable solo si ningun rol no confiable puede CREATE en el',
                       'pg_temp','debe ir explicito y al final: omitirlo lo pone primero (doc PostgreSQL 5.9.3)'));

  -- Vias alternativas de escritura. NO se considera seguro un flujo por sus
  -- permisos de frontend: se miran los grants reales de la base.
  SELECT (CASE WHEN has_table_privilege('authenticated','public.comprobante_payments','INSERT')
               AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='trg_cp_annulled_guard') THEN 1 ELSE 0 END)
       + (CASE WHEN has_table_privilege('authenticated','public.comprobantes','UPDATE')
               AND NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgname='trg_comprobante_annulment_transition') THEN 1 ELSE 0 END)
       + (CASE WHEN has_table_privilege('anon','public.comprobante_payments','INSERT') THEN 1 ELSE 0 END)
       + (CASE WHEN has_table_privilege('authenticated','public.comprobante_payments','DELETE') THEN 1 ELSE 0 END)
    INTO n;
  v_c := v_c || finance_hc_mk('alternative_write_paths','security','Vías alternativas de anulación o cobro',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Toda anulación y todo cobro pasan por su RPC canónica o su guard'
         ELSE n||' vía(s) permiten anular o cobrar sin la RPC canónica' END,
    jsonb_build_object(
      'authenticated_insert_pagos', has_table_privilege('authenticated','public.comprobante_payments','INSERT'),
      'guard_pagos_anulados',       EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='trg_cp_annulled_guard'),
      'authenticated_update_comprobantes', has_table_privilege('authenticated','public.comprobantes','UPDATE'),
      'guard_transicion_anulacion', EXISTS(SELECT 1 FROM pg_trigger WHERE tgname='trg_comprobante_annulment_transition')));

  -- HOTFIX 20260719 — Vistas expuestas que corren con privilegios del OWNER.
  -- Una vista sin security_invoker se evalua como su owner (postgres), que no
  -- esta sujeto a RLS: devuelve filas de TODOS los negocios a cualquier rol con
  -- SELECT. Es el mismo defecto de clase que `secdef_without_search_path`, pero
  -- por la puerta de las vistas.
  --
  -- Se exige la conjuncion (sin invoker) AND (alcanzable por cliente): una
  -- vista interna sin grants no puede filtrar hacia la app. Asi el check no
  -- genera ruido sobre vistas de uso administrativo.
  SELECT count(*) INTO n
    FROM pg_class c
    JOIN pg_namespace ns ON ns.oid = c.relnamespace
   WHERE ns.nspname = 'public'
     AND c.relkind IN ('v','m')
     AND NOT COALESCE(c.reloptions::text[] @> ARRAY['security_invoker=true'], false)
     AND (has_table_privilege('anon', c.oid, 'SELECT')
       OR has_table_privilege('authenticated', c.oid, 'SELECT'));

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'vista', x.relname,
           'anon', x.anon_sel,
           'authenticated', x.auth_sel) ORDER BY x.relname), '[]'::jsonb)
    INTO d
    FROM (SELECT c.relname,
                 has_table_privilege('anon', c.oid, 'SELECT')          AS anon_sel,
                 has_table_privilege('authenticated', c.oid, 'SELECT') AS auth_sel
            FROM pg_class c
            JOIN pg_namespace ns ON ns.oid = c.relnamespace
           WHERE ns.nspname = 'public'
             AND c.relkind IN ('v','m')
             AND NOT COALESCE(c.reloptions::text[] @> ARRAY['security_invoker=true'], false)
             AND (has_table_privilege('anon', c.oid, 'SELECT')
               OR has_table_privilege('authenticated', c.oid, 'SELECT'))) x;

  v_c := v_c || finance_hc_mk('canonical_views_without_security_invoker','security',
    'Vistas expuestas sin security_invoker',
    CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'critical', n, 0,
    CASE WHEN n=0 THEN 'Toda vista alcanzable por anon/authenticated se evalua con los privilegios de quien consulta (RLS activo)'
         ELSE n||' vista(s) alcanzables por anon/authenticated corren con los privilegios de su owner y saltean RLS: exponen datos de todos los negocios' END,
    jsonb_build_object(
      'vistas', d,
      'regla', 'una vista sin security_invoker se evalua como su owner; si el owner no esta sujeto a RLS, el aislamiento por business_id desaparece',
      'remediacion', 'ALTER VIEW public.<vista> SET (security_invoker = true)'));
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- CATEGORIA: reconciliation  (informativa; nunca modifica estados)
  -- ══════════════════════════════════════════════════════════════════════════
  IF v_has_recon THEN
    SELECT count(*) INTO n FROM finance_ledger_reconciliation r
     WHERE r.business_id=v_biz AND r.reconciliation_status='active_inconsistency';
    v_c := v_c || finance_hc_mk('reconciliation_active','reconciliation','Inconsistencias activas registradas',
      CASE WHEN n=0 THEN 'pass' ELSE 'fail' END, 'high', n, 0,
      CASE WHEN n=0 THEN 'Sin inconsistencias activas' ELSE n||' inconsistencia(s) marcadas como activas' END);

    SELECT count(*) INTO n FROM finance_ledger_reconciliation r
     WHERE r.business_id=v_biz AND r.reconciliation_status='indeterminate';
    v_c := v_c || finance_hc_mk('reconciliation_indeterminate','reconciliation','Reconciliaciones indeterminadas',
      CASE WHEN n=0 THEN 'pass' ELSE 'warn' END, 'medium', n, 0,
      CASE WHEN n=0 THEN 'Sin casos indeterminados' ELSE n||' caso(s) sin resolución determinada' END);

    SELECT count(*) INTO n FROM finance_ledger_reconciliation r
     WHERE r.business_id=v_biz AND r.reconciliation_status='corrected';
    v_c := v_c || finance_hc_mk('reconciliation_corrected','reconciliation','Reconciliaciones corregidas',
      CASE WHEN n=0 THEN 'pass' ELSE 'info' END, 'info', n, 0,
      CASE WHEN n=0 THEN 'Sin correcciones registradas'
           ELSE n||' inconsistencia(s) histórica(s) corregidas y explicadas (p. ej. la reconciliación 7B del remito legacy)' END);

    SELECT count(*) INTO n FROM finance_ledger_reconciliation r
     WHERE r.business_id=v_biz AND r.reconciliation_status='legacy_accepted';
    v_c := v_c || finance_hc_mk('reconciliation_legacy_accepted','reconciliation','Legacy aceptado',
      CASE WHEN n=0 THEN 'pass' ELSE 'info' END, 'info', n, 0,
      CASE WHEN n=0 THEN 'Sin deuda legacy aceptada' ELSE n||' caso(s) legacy aceptados y documentados' END);
  END IF;

  -- ══════════════════════════════════════════════════════════════════════════
  -- Resumen  (contrato v1 + campos v2 aditivos)
  -- ══════════════════════════════════════════════════════════════════════════
  RETURN jsonb_build_object(
    -- v1 (frontend actual)
    'ok',             true,
    'business_id',    v_biz,
    'checked_at',     now(),
    'critical_count', (SELECT count(*) FROM jsonb_array_elements(v_c) e WHERE e->>'status'='critical'),
    'warning_count',  (SELECT count(*) FROM jsonb_array_elements(v_c) e WHERE e->>'status'='warning'),
    'low_count',      (SELECT count(*) FROM jsonb_array_elements(v_c) e WHERE e->>'status'='low'),
    'total_issues',   (SELECT COALESCE(SUM((e->>'count')::bigint),0) FROM jsonb_array_elements(v_c) e WHERE e->>'status'<>'ok'),
    'checks',         v_c,
    -- v2 aditivo
    'version',        'm7_health_v2',
    'overall_status', CASE
                        WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_c) e WHERE e->>'result'='fail') THEN 'fail'
                        WHEN EXISTS (SELECT 1 FROM jsonb_array_elements(v_c) e WHERE e->>'result'='warn') THEN 'warn'
                        ELSE 'pass' END,
    'info_count',     (SELECT count(*) FROM jsonb_array_elements(v_c) e WHERE e->>'result'='info'),
    'pass_count',     (SELECT count(*) FROM jsonb_array_elements(v_c) e WHERE e->>'result'='pass'),
    'checks_total',   jsonb_array_length(v_c),
    'duration_ms',    round(EXTRACT(epoch FROM (clock_timestamp()-v_t0))*1000)::int,
    'amount_at_risk', (SELECT COALESCE(SUM((e->>'amount_ars')::numeric),0) FROM jsonb_array_elements(v_c) e WHERE e->>'result'='fail'),
    'schema_state',   jsonb_build_object('ledger', v_has_ledger, 'audit_log', v_has_audit,
                                         'period_locks', v_has_locks, 'reconciliation', v_has_recon,
                                         'payment_replacement', v_has_repl, 'annulment_date', v_has_anndate),
    'semantics',      jsonb_build_object(
        'credit_note', 'La NC revierte ingreso/cobro. El COGS se revierte SOLO si hubo devolucion fisica o restauracion de inventario. Una NC total sin retorno de mercaderia puede producir legitimamente ventas netas cero, COGS positivo y perdida.',
        'legacy_debt', 'Los mirrors de anulacion con clase legacy_unclassified, vinculados uno a uno con su anulacion y fuera del operating result, son deuda de clasificacion explicada (info), no un error activo.')
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.reverse_customer_account_payment_atomic(p_business_id uuid, p_movement_id uuid, p_reason text, p_idempotency_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  c_key_max       constant int := 200;
  v_user          uuid := auth.uid();
  v_is_member     boolean := false;
  v_reason        text := NULLIF(btrim(COALESCE(p_reason,'')), '');
  v_key           text := NULLIF(btrim(COALESCE(p_idempotency_key,'')), '');
  v_hash          text;
  v_existing      public.account_payment_reversals%ROWTYPE;
  v_orig          public.account_movements%ROWTYPE;
  v_fm            public.financial_movements%ROWTYPE;
  v_bfe           public.business_finance_entries%ROWTYPE;
  v_alloc_n       int;
  v_date          date;
  v_new_mov       uuid;
  v_new_fm        uuid;
  v_new_bfe       uuid;
  v_rev_id        uuid;
  v_new_balance   numeric;
  v_stage         text := 'init';
BEGIN
  IF v_user IS NULL THEN RETURN jsonb_build_object('ok', false, 'error_code','UNAUTHORIZED', 'error', 'No autenticado'); END IF;
  IF v_reason IS NULL THEN RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR', 'error', 'El motivo de la reversa es obligatorio'); END IF;
  IF v_key IS NOT NULL AND length(v_key) > c_key_max THEN RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR', 'error', 'La clave de idempotencia es demasiado larga'); END IF;

  SELECT (EXISTS (SELECT 1 FROM public.businesses WHERE id=p_business_id AND owner_user_id=v_user)
       OR EXISTS (SELECT 1 FROM public.profiles WHERE business_id=p_business_id AND COALESCE(user_id,id)=v_user AND COALESCE(is_active,true))) INTO v_is_member;
  IF NOT v_is_member THEN RETURN jsonb_build_object('ok', false, 'error_code','FORBIDDEN', 'error', 'Sin acceso a este negocio'); END IF;
  IF NOT public.current_user_can('finance') THEN
    RETURN jsonb_build_object('ok', false, 'error_code','FORBIDDEN', 'error', 'Sin permiso para operaciones financieras'); END IF;

  -- Replay por clave: se responde ANTES de resolver fecha, guards y escrituras.
  -- El hash NO incluye la fecha: un reintento al día siguiente sigue siendo replay.
  IF v_key IS NOT NULL THEN
    v_hash := encode(extensions.digest(jsonb_build_object(
      'op','customer_account_payment_reversal', 'business_id',p_business_id,
      'movement_id',p_movement_id, 'reason',v_reason)::text, 'sha256'), 'hex');
    SELECT * INTO v_existing FROM public.account_payment_reversals WHERE business_id=p_business_id AND idempotency_key=v_key;
    IF FOUND THEN
      IF v_existing.request_hash IS DISTINCT FROM v_hash THEN
        RETURN jsonb_build_object('ok', false, 'error_code','IDEMPOTENCY_CONFLICT', 'error', 'IDEMPOTENCY_CONFLICT', 'message', 'Esta clave ya fue utilizada con datos diferentes'); END IF;
      RETURN jsonb_build_object('ok', true, 'replay', true,
        'reversal_movement_id', v_existing.reversal_movement_id,
        'reversal_financial_movement_id', v_existing.reversal_financial_movement_id);
    END IF;
  END IF;

  -- LOCK del cobro original: serializa contra dos reversas con claves DISTINTAS.
  SELECT * INTO v_orig FROM public.account_movements
    WHERE id=p_movement_id AND business_id=p_business_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error_code','NOT_FOUND', 'error', 'El cobro no existe en este negocio'); END IF;
  IF v_orig.type <> 'pago' OR v_orig.credit <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR', 'error', 'El movimiento indicado no es un cobro de cuenta corriente'); END IF;

  -- Ya reversado: lo dice el UNIQUE, no el hash. Se lee bajo el lock.
  IF EXISTS (SELECT 1 FROM public.account_payment_reversals WHERE original_movement_id=p_movement_id) THEN
    RETURN jsonb_build_object('ok', false, 'error_code','ALREADY_REVERSED', 'error', 'Este cobro ya fue reversado'); END IF;

  -- Este movimiento NO puede ser, a su vez, la reversa de otro cobro.
  IF v_orig.reference_type = 'account_payment_reversal' THEN
    RETURN jsonb_build_object('ok', false, 'error_code','VALIDATION_ERROR', 'error', 'No se puede reversar una reversa'); END IF;

  -- Imputado: no se deshace en cascada algo que el usuario no pidió.
  SELECT count(*) INTO v_alloc_n FROM public.customer_account_payment_allocations
    WHERE payment_movement_id = p_movement_id AND status = 'active';
  IF v_alloc_n > 0 THEN
    RETURN jsonb_build_object('ok', false, 'error_code','PAYMENT_ALLOCATED',
      'error', 'Este cobro está imputado a comprobantes. Revertí primero la imputación y después el cobro.'); END IF;

  -- Las patas financieras del cobro original, por su enlace canónico.
  SELECT * INTO v_fm FROM public.financial_movements
    WHERE business_id=p_business_id AND reference_type='account_movement' AND reference_id=p_movement_id
    ORDER BY created_at LIMIT 1;
  SELECT * INTO v_bfe FROM public.business_finance_entries
    WHERE business_id=p_business_id AND category='cobro_cuenta_corriente'
      AND date=v_orig.date AND amount_ars=v_orig.credit AND source='cobro_cc'
    ORDER BY created_at LIMIT 1;

  -- La reversa se fecha HOY. Sólo se valida el período de HOY: el mes del cobro
  -- original nunca se reabre.
  v_date := public.ar_today();
  BEGIN
    PERFORM public.assert_period_open(p_business_id, v_date);
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE 'PERIOD_CLOSED%' THEN RETURN jsonb_build_object('ok', false, 'error_code','PERIOD_CLOSED', 'error', SQLERRM);
    ELSIF SQLERRM LIKE 'INVALID_FINANCE_CONTEXT%' THEN RETURN jsonb_build_object('ok', false, 'error_code','INVALID_FINANCE_CONTEXT', 'error', SQLERRM);
    ELSE RAISE; END IF;
  END;

  PERFORM public.finance_begin_audit_scope();
  v_stage := 'write';

  -- (a) Ledger: contra-movimiento que devuelve la deuda. No se borra el cobro.
  INSERT INTO public.account_movements (business_id, account_id, date, type, description, debit, credit, balance_after, reference_type, reference_id, created_by)
    VALUES (p_business_id, v_orig.account_id, v_date, 'ajuste',
      'REVERSO cobro — ' || v_reason, v_orig.credit, 0, 0,
      'account_payment_reversal', p_movement_id, v_user)
    RETURNING id INTO v_new_mov;

  -- (b) Caja: FM compensatorio `expense`, mismo método (no se reclasifica),
  --     en la caja abierta actual (caja_id NULL -> el trigger la asigna).
  IF v_fm.id IS NOT NULL THEN
    INSERT INTO public.financial_movements (business_id, date, type, currency, amount, amount_ars, exchange_rate,
      source, description, created_by, metodo_pago, reference_id, reference_type)
      VALUES (p_business_id, v_date, 'expense', v_fm.currency, v_fm.amount, v_fm.amount_ars, v_fm.exchange_rate,
        'reversal', 'REVERSO cobro de cuenta corriente', v_user, v_fm.metodo_pago,
        p_movement_id, 'account_payment_reversal')
      RETURNING id INTO v_new_fm;
  END IF;

  -- (c) BFE compensatorio: income NEGATIVO, espejo, fuera del P&L.
  IF v_bfe.id IS NOT NULL THEN
    INSERT INTO public.business_finance_entries (business_id, date, type, category, description,
      amount, currency, amount_ars, exchange_rate, payment_method, source, created_by, economic_class)
      VALUES (p_business_id, v_date, 'income', v_bfe.category, 'REVERSO cobro de cuenta corriente — ' || v_reason,
        -v_bfe.amount, v_bfe.currency, -v_bfe.amount_ars, v_bfe.exchange_rate, v_bfe.payment_method,
        'reversal', v_user, 'revenue_collection_mirror')
      RETURNING id INTO v_new_bfe;
  END IF;

  SELECT balance_after INTO v_new_balance FROM public.account_movements WHERE id=v_new_mov;

  -- (d) Registro de la reversa. El UNIQUE sobre original_movement_id es lo que
  --     hace imposible la doble reversa aun con claves distintas.
  INSERT INTO public.account_payment_reversals (business_id, account_id, original_movement_id,
    original_financial_movement_id, original_finance_entry_id,
    reversal_movement_id, reversal_financial_movement_id, reversal_finance_entry_id,
    amount_ars, reason, created_by, idempotency_key, request_hash, op, metadata)
    VALUES (p_business_id, v_orig.account_id, p_movement_id, v_fm.id, v_bfe.id,
      v_new_mov, v_new_fm, v_new_bfe, v_orig.credit, v_reason, v_user, v_key, v_hash,
      'customer_account_payment_reversal',
      jsonb_build_object('method', v_fm.metodo_pago, 'original_date', v_orig.date, 'reversal_date', v_date))
    RETURNING id INTO v_rev_id;

  v_stage := 'audit';
  PERFORM public.finance_log_audit(
    p_business_id, 'customer_account_payment_reversal', 'account_movements', p_movement_id,
    'reverse_customer_account_payment_atomic',
    v_key, v_reason, v_date, 'account', v_orig.account_id,
    NULL, jsonb_build_object('reversal_id', v_rev_id, 'original_movement_id', p_movement_id,
      'reversal_movement_id', v_new_mov, 'amount_ars', v_orig.credit,
      'original_financial_movement_id', v_fm.id, 'reversal_financial_movement_id', v_new_fm,
      'original_finance_entry_id', v_bfe.id, 'reversal_finance_entry_id', v_new_bfe,
      'method', v_fm.metodo_pago, 'original_date', v_orig.date, 'reversal_date', v_date,
      'original_period', to_char(v_orig.date,'YYYY-MM'), 'reversal_period', to_char(v_date,'YYYY-MM'),
      'new_balance', v_new_balance, 'reason', v_reason));

  RETURN jsonb_build_object('ok', true, 'replay', false,
    'reversal_id', v_rev_id, 'reversal_movement_id', v_new_mov,
    'reversal_financial_movement_id', v_new_fm, 'reversal_finance_entry_id', v_new_bfe,
    'balance', v_new_balance);
EXCEPTION
  -- Carrera real: dos reversas simultáneas con claves distintas. El UNIQUE gana.
  WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', false, 'error_code','ALREADY_REVERSED', 'error', 'Este cobro ya fue reversado');
  WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false,
      'error_code', CASE WHEN v_stage='audit' THEN 'AUDIT_FAILED' ELSE 'INTERNAL_ERROR' END,
      'error', CASE WHEN v_stage='audit' THEN 'No se pudo registrar la auditoría de la operación'
                    ELSE 'No se pudo completar la operación' END);
END;
$function$

CREATE OR REPLACE FUNCTION public.cap_alloc_integrity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_mov     public.account_movements%ROWTYPE;
  v_comp    public.comprobantes%ROWTYPE;
  v_acc_biz uuid;
  v_acc_cus uuid;
  v_pago    numeric;
  v_asig    numeric;
  v_saldo   numeric;
  v_aplic   numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'customer_account_payment_allocations es append-only: DELETE no permitido'
      USING ERRCODE = '0A000';
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Sólo se permite cerrar una asignación (reversa). Los importes y las
    -- referencias son inmutables.
    IF NEW.business_id IS DISTINCT FROM OLD.business_id
       OR NEW.customer_id IS DISTINCT FROM OLD.customer_id
       OR NEW.account_id IS DISTINCT FROM OLD.account_id
       OR NEW.payment_movement_id IS DISTINCT FROM OLD.payment_movement_id
       OR NEW.comprobante_id IS DISTINCT FROM OLD.comprobante_id
       OR NEW.amount IS DISTINCT FROM OLD.amount
       OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key THEN
      RAISE EXCEPTION 'La asignación es inmutable: sólo puede pasar a reversed'
        USING ERRCODE = '0A000';
    END IF;
    RETURN NEW;
  END IF;

  -- ── INSERT ────────────────────────────────────────────────────────────────
  SELECT * INTO v_mov FROM public.account_movements WHERE id = NEW.payment_movement_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PAYMENT_NOT_FOUND: el movimiento de pago no existe' USING ERRCODE = '23503';
  END IF;
  SELECT * INTO v_comp FROM public.comprobantes WHERE id = NEW.comprobante_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COMPROBANTE_NOT_FOUND' USING ERRCODE = '23503';
  END IF;
  SELECT a.business_id, a.entity_id INTO v_acc_biz, v_acc_cus
    FROM public.accounts a WHERE a.id = NEW.account_id;

  -- Aislamiento total: negocio y cliente coherentes en las cuatro puntas.
  IF v_mov.business_id IS DISTINCT FROM NEW.business_id
     OR v_comp.business_id IS DISTINCT FROM NEW.business_id
     OR v_acc_biz IS DISTINCT FROM NEW.business_id THEN
    RAISE EXCEPTION 'ALLOCATION_CROSS_BUSINESS: pago, comprobante, cuenta y negocio no coinciden'
      USING ERRCODE = '42501';
  END IF;
  IF v_mov.account_id IS DISTINCT FROM NEW.account_id THEN
    RAISE EXCEPTION 'ALLOCATION_WRONG_ACCOUNT: el pago no pertenece a esa cuenta'
      USING ERRCODE = '42501';
  END IF;
  IF v_acc_cus IS DISTINCT FROM NEW.customer_id
     OR (v_comp.customer_id IS NOT NULL AND v_comp.customer_id IS DISTINCT FROM NEW.customer_id) THEN
    RAISE EXCEPTION 'ALLOCATION_CROSS_CUSTOMER: el comprobante no es del cliente de la cuenta'
      USING ERRCODE = '42501';
  END IF;

  -- El movimiento imputado debe ser un COBRO (credit > 0), no una venta.
  IF COALESCE(v_mov.credit, 0) <= 0 THEN
    RAISE EXCEPTION 'ALLOCATION_NOT_A_PAYMENT: sólo se imputan cobros de cuenta corriente'
      USING ERRCODE = '22023';
  END IF;

  -- Un comprobante anulado no admite imputación.
  IF v_comp.estado = 'anulado' OR v_comp.status = 'cancelled' OR v_comp.estado_comercial = 'anulado' THEN
    RAISE EXCEPTION 'ALLOCATION_ON_ANNULLED: el comprobante está anulado' USING ERRCODE = '22023';
  END IF;

  -- Σ asignaciones activas <= importe del pago.
  v_pago := COALESCE(v_mov.credit, 0);
  SELECT COALESCE(SUM(amount), 0) INTO v_asig
    FROM public.customer_account_payment_allocations
   WHERE payment_movement_id = NEW.payment_movement_id AND status = 'active' AND id <> NEW.id;
  IF v_asig + NEW.amount > v_pago + 0.01 THEN
    RAISE EXCEPTION 'ALLOCATION_EXCEEDS_PAYMENT: el pago tiene % disponible y se intentó imputar %',
      round(v_pago - v_asig, 2), NEW.amount USING ERRCODE = '22023';
  END IF;

  -- Σ aplicado al comprobante <= saldo imputable del documento.
  v_saldo := COALESCE(v_comp.saldo_pendiente, 0);
  SELECT COALESCE(SUM(amount), 0) INTO v_aplic
    FROM public.customer_account_payment_allocations
   WHERE comprobante_id = NEW.comprobante_id AND status = 'active' AND id <> NEW.id;
  IF v_aplic + NEW.amount > v_saldo + 0.01 THEN
    RAISE EXCEPTION 'ALLOCATION_EXCEEDS_BALANCE: el comprobante tiene % imputable y se intentó imputar %',
      round(v_saldo - v_aplic, 2), NEW.amount USING ERRCODE = '22023';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.pay_comprobante_from_account_atomic(p_business_id uuid, p_account_id uuid, p_comprobante_id uuid, p_amount numeric, p_description text, p_payment_method text, p_date date, p_caja_id uuid, p_user_id uuid, p_idempotency_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_key   text := NULLIF(btrim(COALESCE(p_idempotency_key, '')), '');
  v_pay   jsonb;
  v_alloc jsonb;
  v_mov   uuid;
  v_saldo numeric;
  v_imp   numeric;
BEGIN

  -- LOTE 2: actor -> canonical active tenant -> existing action authority.
  PERFORM public._require_business_member(p_business_id);
  IF p_business_id IS DISTINCT FROM public.current_user_business_id()
     OR NOT public.current_user_can('finance') THEN
    RAISE EXCEPTION 'FORBIDDEN' USING ERRCODE = '42501';
  END IF;
  IF v_key IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'VALIDATION_ERROR', 'error', 'idempotency_key requerida');
  END IF;

  -- Saldo imputable del documento: el excedente NO se imputa, queda como crédito.
  SELECT GREATEST(COALESCE(c.saldo_pendiente, 0)
         - COALESCE((SELECT SUM(al.amount) FROM public.customer_account_payment_allocations al
                      WHERE al.comprobante_id = c.id AND al.status = 'active'), 0), 0)
    INTO v_saldo
    FROM public.comprobantes c
   WHERE c.id = p_comprobante_id AND c.business_id = p_business_id;
  IF v_saldo IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error_code', 'COMPROBANTE_NOT_FOUND', 'error', 'Comprobante no encontrado');
  END IF;

  v_pay := public.record_customer_account_payment_atomic(
    p_business_id, p_account_id, p_amount, p_description, p_user_id,
    p_payment_method, p_date, p_caja_id, v_key);
  IF COALESCE((v_pay->>'ok')::boolean, false) IS NOT TRUE THEN
    RETURN v_pay;
  END IF;
  v_mov := (v_pay->>'account_movement_id')::uuid;

  v_imp := LEAST(ROUND(p_amount, 2), v_saldo);
  IF v_imp > 0 THEN
    v_alloc := public.allocate_account_payment_atomic(
      p_business_id, v_mov,
      jsonb_build_array(jsonb_build_object('comprobante_id', p_comprobante_id, 'amount', v_imp)),
      'Cobro imputado desde el comprobante', v_key || ':auto');
    IF COALESCE((v_alloc->>'ok')::boolean, false) IS NOT TRUE THEN
      RAISE EXCEPTION 'ALLOCATION_FAILED: %', COALESCE(v_alloc->>'error', 'sin detalle');
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true,
    'account_movement_id', v_mov,
    'allocated_amount', v_imp,
    'unallocated_amount', ROUND(p_amount, 2) - v_imp,
    'payment', v_pay, 'allocation', v_alloc);
END;
$function$

CREATE OR REPLACE FUNCTION public.current_user_can_in_business(p_business_id uuid, p_key text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'pg_temp'
AS $function$
DECLARE
  v_uid uuid; v_role text; v_perms jsonb;
BEGIN
  v_uid := auth.uid();
  IF v_uid IS NULL OR p_business_id IS NULL OR p_key IS NULL THEN RETURN false; END IF;

  IF EXISTS (
    SELECT 1 FROM public.businesses
     WHERE id = p_business_id AND owner_user_id = v_uid
  ) THEN
    RETURN private.capability_resolve('owner', NULL::jsonb, p_key);
  END IF;

  SELECT p.role, p.permissions INTO v_role, v_perms
    FROM public.profiles p
   WHERE p.business_id = p_business_id
     AND COALESCE(p.user_id, p.id) = v_uid
     AND COALESCE(p.is_active, true)
   ORDER BY COALESCE(p.updated_at, p.created_at, now()) DESC
   LIMIT 1;

  RETURN private.capability_resolve(v_role, v_perms, p_key);
END;
$function$

CREATE OR REPLACE FUNCTION public.check_client_contract()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'private'
AS $function$
DECLARE
  v_request_role text := current_setting('role', true);
  v_claims jsonb;
  v_claim_role text;
  v_state text;
  v_minimum bigint;
  v_header text;
BEGIN
  BEGIN
    v_claims := coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb;
  EXCEPTION WHEN invalid_text_representation THEN
    v_claims := '{}'::jsonb;
  END;
  v_claim_role := v_claims ->> 'role';

  IF v_request_role = 'anon' AND (v_claim_role = 'anon' OR v_claim_role IS NULL) THEN
    RETURN;
  END IF;

  IF v_request_role = 'service_role' AND v_claim_role = 'service_role' THEN
    RETURN;
  END IF;

  IF v_request_role <> 'authenticated' OR v_claim_role <> 'authenticated' THEN
    RAISE SQLSTATE 'PGRST' USING
      MESSAGE = '{"code":"CLIENT_CONTRACT_IDENTITY_ERROR","message":"No se pudo validar el cliente."}',
      DETAIL = '{"status":403,"headers":{}}';
  END IF;

  SELECT enforcement_state, minimum_contract
    INTO v_state, v_minimum
    FROM private.client_contract_config
   WHERE singleton IS TRUE;

  IF NOT FOUND OR v_state NOT IN ('disabled', 'enabled')
     OR (v_state = 'disabled' AND v_minimum IS NOT NULL)
     OR (v_state = 'enabled' AND (v_minimum IS NULL OR v_minimum < 0)) THEN
    RAISE SQLSTATE 'PGRST' USING
      MESSAGE = '{"code":"CLIENT_CONTRACT_CONFIGURATION_ERROR","message":"Servicio temporalmente no disponible."}',
      DETAIL = '{"status":503,"headers":{}}';
  END IF;

  IF v_state = 'disabled' THEN
    RETURN;
  END IF;

  BEGIN
    v_header := coalesce(current_setting('request.headers', true), '{}')::jsonb
      ->> 'x-techrepair-client-contract';
  EXCEPTION WHEN invalid_text_representation THEN
    v_header := NULL;
  END;

  IF v_header IS NULL OR v_header !~ '^(0|[1-9][0-9]*)$' THEN
    RAISE SQLSTATE 'PGRST' USING
      MESSAGE = '{"code":"CLIENT_UPDATE_REQUIRED","message":"Actualizá la aplicación para continuar."}',
      DETAIL = '{"status":409,"headers":{}}';
  END IF;

  IF v_header::numeric < v_minimum THEN
    RAISE SQLSTATE 'PGRST' USING
      MESSAGE = '{"code":"CLIENT_UPDATE_REQUIRED","message":"Actualizá la aplicación para continuar."}',
      DETAIL = '{"status":409,"headers":{}}';
  END IF;
END;
$function$
